/**
 * verify-component.mjs — the single merged UI-tier verifier gate.
 *
 * Collapses 20 UI-tier gates into one CLI with sub-checks. Each former gate is
 * a `check_<slug>()` function returning its exit code; every module-level const/
 * regex/helper of a gate lives INSIDE its function (closure) so names cannot
 * collide across gates. Spec.yaml structured reads route through loadSpec().
 *
 * Dispatch:
 *   node verify-component.mjs                     → run all sub-checks except ui-screenshots (exit 1 iff any fail)
 *   node verify-component.mjs --full              → all + ui-screenshots-match-designs
 *   node verify-component.mjs --check <slug> [src] → run only that sub-check
 *
 * The ui-components-compliance audit is exported as `runAudit` for its selftest.
 */

import fs, {
  readdirSync,
  readFileSync,
  existsSync,
  statSync,
  mkdirSync,
  writeFileSync,
} from "node:fs";
import path, { join, relative, basename, dirname, resolve, sep } from "node:path";
import { execSync } from "node:child_process";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";
import process from "node:process";

import {
  discoverComponents,
  discoverSpeccedComponents,
  makeIsUnderComponent,
  makeComponentDirOf,
} from "./_discover-components.mjs";
import {
  applyExceptions,
  applyExceptionsByFolder,
  loadExceptions,
} from "./_load-exceptions.mjs";
import {
  loadSpec,
  loadLock,
  resolveSpecFile,
  resolveLockFile,
  specFileExists,
  extractFencedYaml,
} from "../lib/load-spec.mjs";
import { resolveDesign } from "../lib/design-source.mjs";

/**
 * Machine YAML text for a __specs__ dir, dual-format: the fenced ```yaml block
 * of spec.md when present, else the raw legacy spec.yaml. null when neither
 * exists. Used by the raw-text-regex spec checks so they see the SAME machine
 * content whether the spec was authored as Markdown or legacy YAML.
 */
function specMachineText(specsDir) {
  const file = resolveSpecFile(specsDir);
  if (!fs.existsSync(file)) return null;
  const raw = fs.readFileSync(file, "utf8");
  return file.endsWith(".md") ? extractFencedYaml(raw) : raw;
}

// ===========================================================================
// ui-components-compliance — module-scope helpers (runAudit is an export the
// gate's selftest imports; helpers are uniquely named so they never collide).
// ===========================================================================

const __filename = fileURLToPath(import.meta.url);
const SCRIPT_DIR = dirname(__filename);
const ROOT_DIR = resolve(SCRIPT_DIR, "..", "..");

const VIOLATION_PREFIX =
  "G-UI-COMPONENTS violation: a check defined in COMPONENT_FOLDERS.yaml + COMPONENT_LIBRARY_DOCTRINE.yaml failed.";

const SHADE_RE = new RegExp(
  "(?:^|\\s|[\"'`{(])((?:text|bg|border|from|to|via|ring|outline|divide|accent|fill|stroke|shadow|placeholder|caret)" +
    "-" +
    "(red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose|slate|gray|zinc|neutral|stone)" +
    "(?:-(?:50|100|200|300|400|500|600|700|800|900|950))?)(?:[/\\s\"'`)}]|$)",
  "g",
);

const BLACK_WHITE_RE = new RegExp(
  "(?:^|\\s|[\"'`{(])((?:text|bg|border|ring|fill|stroke|shadow|placeholder|caret)" +
    "-(?:black|white))(?:/\\d+)?(?:[\\s\"'`)}]|$)",
  "g",
);

const SHADE_EXEMPT_DIRS = [
  /^src\/components\/shadcn\//,
  /^src\/i18n\/messages\//,
];

const STANDARD_DIRS = [
  "src/components/shadcn",
  "src/components/ui",
  "src/features",
  "src/app",
  "src/hooks",
  "src/lib",
  "src/i18n",
  "src/middleware.ts",
];

export function collectFiles(dir) {
  const result = [];
  const stack = [dir];
  while (stack.length > 0) {
    const current = stack.pop();
    let entries;
    try {
      entries = readdirSync(current);
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = join(current, entry);
      let stats;
      try {
        stats = statSync(full);
      } catch {
        continue;
      }
      if (stats.isDirectory()) {
        if (entry === "node_modules" || entry === ".next" || entry === "dist") {
          continue;
        }
        stack.push(full);
      } else if (
        stats.isFile() &&
        (entry.endsWith(".ts") || entry.endsWith(".tsx"))
      ) {
        result.push(full);
      }
    }
  }
  return result;
}

export function isShadeExempt(rel) {
  return SHADE_EXEMPT_DIRS.some((re) => re.test(rel));
}

export function findShadeViolations(content) {
  const out = [];
  const lines = content.split("\n");
  let inBlockComment = false;
  for (let i = 0; i < lines.length; i += 1) {
    let code = lines[i];
    if (inBlockComment) {
      const close = code.indexOf("*/");
      if (close === -1) continue;
      code = code.slice(close + 2);
      inBlockComment = false;
    }
    while (true) {
      const open = code.indexOf("/*");
      if (open === -1) break;
      const close = code.indexOf("*/", open + 2);
      if (close === -1) {
        inBlockComment = true;
        code = code.slice(0, open);
        break;
      }
      code = code.slice(0, open) + code.slice(close + 2);
    }
    const lineCommentIdx = code.indexOf("//");
    if (lineCommentIdx !== -1) code = code.slice(0, lineCommentIdx);

    SHADE_RE.lastIndex = 0;
    let m;
    while ((m = SHADE_RE.exec(code)) !== null) {
      out.push({ line: i + 1, hit: m[1] });
    }
    BLACK_WHITE_RE.lastIndex = 0;
    while ((m = BLACK_WHITE_RE.exec(code)) !== null) {
      out.push({ line: i + 1, hit: m[1] });
    }
  }
  return out;
}

export function collectComponentFolders(rootDir) {
  const folders = [];
  const uiDir = join(rootDir, "src", "components", "ui");
  try {
    for (const entry of readdirSync(uiDir)) {
      const p = join(uiDir, entry);
      if (statSync(p).isDirectory() && /^[A-Z]/.test(entry)) folders.push(p);
    }
  } catch {
    /* ui dir may not exist */
  }
  const featuresDir = join(rootDir, "src", "features");
  try {
    for (const feature of readdirSync(featuresDir)) {
      const compRoot = join(featuresDir, feature, "components");
      try {
        for (const entry of readdirSync(compRoot)) {
          const p = join(compRoot, entry);
          if (statSync(p).isDirectory() && /^[A-Z]/.test(entry)) {
            folders.push(p);
          }
        }
      } catch {
        /* feature has no components/ subdir */
      }
    }
  } catch {
    /* features dir may not exist */
  }
  return folders;
}

export function auditFolderShape(folder) {
  const name = basename(folder);
  const required = [
    `${name}.tsx`,
    "index.ts",
    `__tests__/${name}.test.tsx`,
    `__stories__/${name}.stories.tsx`,
  ];
  const missing = [];
  for (const rel of required) {
    try {
      statSync(join(folder, rel));
    } catch {
      missing.push(rel);
    }
  }
  // spec + lock are dual-format: present if either the .md (fenced) or legacy .yaml exists.
  const specsDir = join(folder, "__specs__");
  if (!specFileExists(specsDir)) missing.push("__specs__/spec.yaml");
  if (!existsSync(resolveLockFile(specsDir))) missing.push("__specs__/standards-compliance.yaml");
  return missing.length === 0 ? null : { folder, missing };
}

export function findMisplacedComponents(rootDir) {
  const out = [];
  const compRoot = join(rootDir, "src", "components");
  try {
    for (const entry of readdirSync(compRoot)) {
      const p = join(compRoot, entry);
      const stat = statSync(p);
      if (stat.isDirectory() && (entry === "shadcn" || entry === "ui")) continue;
      if (stat.isFile() && (entry.endsWith(".tsx") || entry.endsWith(".ts"))) {
        out.push(
          relative(rootDir, p).split(sep).join("/"),
        );
      }
    }
  } catch {
    /* components dir may not exist */
  }
  const uiDir = join(rootDir, "src", "components", "ui");
  try {
    for (const entry of readdirSync(uiDir)) {
      const p = join(uiDir, entry);
      const stat = statSync(p);
      if (stat.isFile() && (entry.endsWith(".tsx") || entry.endsWith(".ts"))) {
        out.push(relative(rootDir, p).split(sep).join("/"));
      }
    }
  } catch {
    /* ui dir may not exist */
  }
  return out;
}

export function runAudit(rootDir = ROOT_DIR) {
  const srcDir = join(rootDir, "src");
  const files = collectFiles(srcDir);

  // ---------- GATE-1 + GATE-3: folder shape + placement ----------
  const componentFolders = collectComponentFolders(rootDir);
  const shapeIssues = [];
  for (const folder of componentFolders) {
    const issue = auditFolderShape(folder);
    if (issue) shapeIssues.push(issue);
  }
  const misplaced = findMisplacedComponents(rootDir);

  // ---------- GATE-2: shade-class violations ----------
  const shadeIssues = [];
  for (const f of files) {
    const rel = relative(rootDir, f).split(sep).join("/");
    if (isShadeExempt(rel)) continue;
    const content = (() => {
      try {
        return readFileSync(f, "utf8");
      } catch {
        return "";
      }
    })();
    const hits = findShadeViolations(content);
    if (hits.length > 0) shadeIssues.push({ path: rel, hits });
  }

  // ---------- report ----------
  const fail =
    shapeIssues.length > 0 ||
    misplaced.length > 0 ||
    shadeIssues.length > 0;

  if (!fail) {
    process.stdout.write(
      `[verify-ui-components-compliance] PASS — ${componentFolders.length} component folder(s) checked; no shade classes in non-shadcn code; no misplaced components.\n`,
    );
    return 0;
  }

  process.stderr.write(`${VIOLATION_PREFIX}\n\n`);
  if (shapeIssues.length > 0) {
    process.stderr.write(
      "GATE-1 — Component folders missing required files:\n",
    );
    for (const s of shapeIssues) {
      const rel = relative(rootDir, s.folder).split(sep).join("/");
      process.stderr.write(`  ${rel}/\n`);
      for (const m of s.missing) process.stderr.write(`    - missing: ${m}\n`);
    }
    process.stderr.write("\n");
  }
  if (misplaced.length > 0) {
    process.stderr.write(
      "GATE-3 — Components in the wrong location (must live in a ComponentName/ folder under src/components/ui/ or src/features/<f>/components/):\n",
    );
    for (const m of misplaced) process.stderr.write(`  ${m}\n`);
    process.stderr.write("\n");
  }
  if (shadeIssues.length > 0) {
    process.stderr.write(
      "GATE-2 — Hardcoded Tailwind shade classes (use semantic tokens from globals.css instead — text-foreground / bg-background / bg-primary / border-border / etc.):\n",
    );
    for (const s of shadeIssues) {
      for (const h of s.hits) {
        process.stderr.write(`  ${s.path}:${h.line} — ${h.hit}\n`);
      }
    }
    process.stderr.write("\n");
  }
  process.stderr.write(
    "Rule reference: `.claude/standards/COMPONENT_FOLDERS.yaml` + `.claude/standards/COMPONENT_LIBRARY_DOCTRINE.yaml` RULE FE-1 / FE-3 / FE-4.\n",
  );
  process.stderr.write(
    "This gate is non-overridable. Fix the violations rather than disabling the gate.\n",
  );
  return 1;
}

export const _constants = {
  SHADE_RE,
  BLACK_WHITE_RE,
  SHADE_EXEMPT_DIRS,
  STANDARD_DIRS,
  VIOLATION_PREFIX,
};

// ===========================================================================
function check_component_tokens(srcRoot = "src") {
  const RULE_ID = "verify-component-tokens";
  const SRC_ROOT = srcRoot;
  const REPO_ROOT = process.cwd();
  const absRoot = join(REPO_ROOT, SRC_ROOT);
  const isUnderComponent = makeIsUnderComponent(absRoot);
  const componentDirOf = makeComponentDirOf(absRoot);

  const IGNORE_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "coverage", ".git",
    "storybook-static",
  ]);

  const SHADCN_SEGMENT = /[\\/]components[\\/]shadcn[\\/]/;
  const STYLES_SEGMENT = /[\\/]styles[\\/]/;
  const STORIES_SEGMENT = /[\\/]__stories__[\\/]/;
  const TESTS_SEGMENT = /[\\/]__tests__[\\/]/;
  const SPECS_SEGMENT = /[\\/]__specs__[\\/]/;

  const PALETTE_NAMES = [
    "slate", "gray", "zinc", "neutral", "stone",
    "red", "orange", "amber", "yellow", "lime",
    "green", "emerald", "teal", "cyan", "sky",
    "blue", "indigo", "violet", "purple", "fuchsia",
    "pink", "rose",
  ];

  const COLOR_UTILITY_PREFIXES = [
    "bg", "text", "border", "ring", "outline",
    "fill", "stroke", "from", "via", "to",
    "shadow", "accent", "caret", "decoration",
    "divide", "placeholder",
  ];

  const PALETTE_CLASS_REGEX = new RegExp(
    String.raw`\b(${COLOR_UTILITY_PREFIXES.join("|")})-(${PALETTE_NAMES.join("|")})-(50|100|200|300|400|500|600|700|800|900|950)(?:\/\d+)?\b`,
    "g",
  );

  const HEX_REGEX = /(?<![A-Za-z0-9])#[0-9a-fA-F]{3,8}\b/g;

  const RGB_HSL_REGEX = /\b(?:rgb|rgba|hsl|hsla)\s*\(/g;

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-component-tokens — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  const componentFiles = [];

  function walk(dir) {
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (IGNORE_DIRS.has(entry.name)) continue;
        walk(full);
        continue;
      }
      if (!entry.isFile()) continue;
      if (!/\.tsx?$/.test(entry.name)) continue;
      if (!isUnderComponent(full)) continue;
      if (SHADCN_SEGMENT.test(full)) continue;
      if (STYLES_SEGMENT.test(full)) continue;
      if (STORIES_SEGMENT.test(full)) continue;
      if (TESTS_SEGMENT.test(full)) continue;
      if (SPECS_SEGMENT.test(full)) continue;
      componentFiles.push(full);
    }
  }

  walk(absRoot);

  if (componentFiles.length === 0) {
    process.stdout.write(
      `✅ verify-component-tokens — no design-system component sources under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
    );
    return 0;
  }

  const violations = [];
  const byDir = new Map();

  function lineNumber(content, idx) {
    return content.slice(0, idx).split("\n").length;
  }

  function* scanRegex(re, content) {
    const flags = re.flags.includes("g") ? re.flags : re.flags + "g";
    const r = new RegExp(re.source, flags);
    let m;
    while ((m = r.exec(content)) !== null) {
      yield { match: m[0], index: m.index };
    }
  }

  for (const filePath of componentFiles) {
    const rel = relative(REPO_ROOT, filePath);
    const content = readFileSync(filePath, "utf8");
    const local = [];

    for (const hit of scanRegex(HEX_REGEX, content)) {
      local.push(
        `${rel}:${lineNumber(content, hit.index)}: hardcoded hex color "${hit.match}" — use Tailwind arbitrary value referencing a CSS var (bg-[var(--color-…)])`,
      );
    }

    for (const hit of scanRegex(RGB_HSL_REGEX, content)) {
      local.push(
        `${rel}:${lineNumber(content, hit.index)}: ${hit.match.replace("(", "").trim()}() literal — use a CSS var instead`,
      );
    }

    for (const hit of scanRegex(PALETTE_CLASS_REGEX, content)) {
      local.push(
        `${rel}:${lineNumber(content, hit.index)}: palette-shade class "${hit.match}" — use Tailwind arbitrary value referencing a CSS var instead`,
      );
    }

    if (local.length) {
      const compDir = componentDirOf(filePath) || dirname(filePath);
      if (!byDir.has(compDir)) byDir.set(compDir, []);
      byDir.get(compDir).push(...local);
    }
  }

  for (const [compDir, local] of byDir) {
    const rel = relative(REPO_ROOT, compDir);
    violations.push(
      ...applyExceptions({ dir: compDir, ruleId: RULE_ID, violations: local, rel }),
    );
  }

  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-component-tokens — ${componentFiles.length} component file(s) checked; all token-disciplined.\n`,
    );
    return 0;
  }

  process.stderr.write(
    `❌ verify-component-tokens: ${violations.length} violation(s)\n\n`,
  );
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write(
    `\nPer COMPONENT_CREATION.yaml.token_discipline, components must reference CSS vars only.\n` +
      `Allowed: bg-[var(--color-primary)], text-[var(--color-foreground)], etc.\n` +
      `Forbidden in src/components/ui/**/*.tsx: hex literals, rgb()/hsl() calls, palette-shade classes.\n`,
  );
  return 1;
}

function check_component_state_vocab(srcRoot = "src") {
  const RULE_ID = "verify-component-state-vocab";
  const SRC_ROOT = srcRoot;
  const REPO_ROOT = process.cwd();
  const absRoot = join(REPO_ROOT, SRC_ROOT);
  const isUnderComponent = makeIsUnderComponent(absRoot);
  const componentDirOf = makeComponentDirOf(absRoot);

  const IGNORE_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "coverage", ".git",
    "storybook-static",
  ]);

  const SHADCN_SEGMENT = /[\\/]components[\\/]shadcn[\\/]/;
  const STYLES_SEGMENT = /[\\/]styles[\\/]/;
  const STORIES_SEGMENT = /[\\/]__stories__[\\/]/;
  const TESTS_SEGMENT = /[\\/]__tests__[\\/]/;
  const SPECS_SEGMENT = /[\\/]__specs__[\\/]/;

  const STATE_VARIANTS = [
    "hover", "focus", "focus-visible", "focus-within", "active", "disabled",
    "group-hover", "group-focus", "peer-hover", "peer-focus", "aria-busy",
    "aria-pressed", "aria-expanded",
  ];

  const STATE_VARIANT_REGEX = new RegExp(
    String.raw`(?<![A-Za-z0-9_-])(${STATE_VARIANTS.join("|")}):[A-Za-z0-9_\-\[\]\(\),:./%]+`,
    "g",
  );

  const STATE_CLASS_REGEX = /\bstate-(?:hover|focus-visible|focus-within|active|pressed|disabled|loading)(?:-[a-z]+)?\b/g;

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-component-state-vocab — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  const componentFiles = [];

  function walk(dir) {
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (IGNORE_DIRS.has(entry.name)) continue;
        walk(full);
        continue;
      }
      if (!entry.isFile()) continue;
      if (!/\.tsx?$/.test(entry.name)) continue;
      if (!isUnderComponent(full)) continue;
      if (SHADCN_SEGMENT.test(full)) continue;
      if (STYLES_SEGMENT.test(full)) continue;
      if (STORIES_SEGMENT.test(full)) continue;
      if (TESTS_SEGMENT.test(full)) continue;
      if (SPECS_SEGMENT.test(full)) continue;
      componentFiles.push(full);
    }
  }

  walk(absRoot);

  if (componentFiles.length === 0) {
    process.stdout.write(
      `✅ verify-component-state-vocab — no design-system component sources under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
    );
    return 0;
  }

  const violations = [];
  const byDir = new Map();

  function lineNumber(content, idx) {
    return content.slice(0, idx).split("\n").length;
  }

  function* scanRegex(re, content) {
    const flags = re.flags.includes("g") ? re.flags : re.flags + "g";
    const r = new RegExp(re.source, flags);
    let m;
    while ((m = r.exec(content)) !== null) {
      yield { match: m[0], index: m.index };
    }
  }

  function checkCvaConsistency(content, filePath, rel, sink) {
    const variantsBlockRegex = /variants\s*:\s*\{/g;
    let m;
    while ((m = variantsBlockRegex.exec(content)) !== null) {
      const startIdx = m.index + m[0].length;
      const blockEnd = findMatchingBrace(content, startIdx);
      if (blockEnd < 0) continue;
      const block = content.slice(startIdx, blockEnd);
      const groupRegex = /([A-Za-z_$][A-Za-z0-9_$]*)\s*:\s*\{/g;
      let g;
      while ((g = groupRegex.exec(block)) !== null) {
        const groupName = g[1];
        const groupStart = g.index + g[0].length;
        const groupEnd = findMatchingBrace(block, groupStart);
        if (groupEnd < 0) continue;
        const groupBody = block.slice(groupStart, groupEnd);
        const entryRegex = /([A-Za-z_$][A-Za-z0-9_$]*)\s*:\s*(['"`])((?:\\.|(?!\2).)*)\2/g;
        const perVariantStateMap = new Map();
        let e;
        while ((e = entryRegex.exec(groupBody)) !== null) {
          const variantKey = e[1];
          const classString = e[3];
          const stateClasses = new Set();
          let sc;
          const r = new RegExp(STATE_CLASS_REGEX.source, "g");
          while ((sc = r.exec(classString)) !== null) {
            stateClasses.add(sc[0]);
          }
          perVariantStateMap.set(variantKey, stateClasses);
        }
        const entries = [...perVariantStateMap.entries()];
        if (entries.length < 2) continue;
        const statePrefixes = new Set();
        for (const [, classes] of entries) {
          for (const cls of classes) {
            const prefix = cls.split("-").slice(0, 2).join("-");
            statePrefixes.add(prefix);
          }
        }
        for (const prefix of statePrefixes) {
          const seen = new Set();
          let anyHasIt = false;
          for (const [, classes] of entries) {
            const matching = [...classes].filter((c) => c.startsWith(prefix + "-") || c === prefix);
            if (matching.length === 0) continue;
            anyHasIt = true;
            for (const cls of matching) seen.add(cls);
          }
          if (anyHasIt && seen.size > 1) {
            sink.push(
              `${rel}: cva group \`${groupName}\` is inconsistent for state \`${prefix}\` — entries bind to: ${[...seen].join(", ")}. All entries within the same variant group must share the same state-class for any given state.`,
            );
          }
        }
      }
    }
  }

  function findMatchingBrace(content, openIdx) {
    let depth = 1;
    for (let i = openIdx; i < content.length; i++) {
      const c = content[i];
      if (c === "{") depth++;
      else if (c === "}") {
        depth--;
        if (depth === 0) return i;
      }
    }
    return -1;
  }

  for (const filePath of componentFiles) {
    const rel = relative(REPO_ROOT, filePath);
    const content = readFileSync(filePath, "utf8");
    const local = [];

    for (const hit of scanRegex(STATE_VARIANT_REGEX, content)) {
      local.push(
        `${rel}:${lineNumber(content, hit.index)}: direct state variant \`${hit.match}\` — bind to a shared state-* class (state-hover-contained, state-focus-visible, etc.) from src/styles/states.css instead`,
      );
    }

    checkCvaConsistency(content, filePath, rel, local);

    if (local.length) {
      const compDir = componentDirOf(filePath) || dirname(filePath);
      if (!byDir.has(compDir)) byDir.set(compDir, []);
      byDir.get(compDir).push(...local);
    }
  }

  for (const [compDir, local] of byDir) {
    const rel = relative(REPO_ROOT, compDir);
    violations.push(
      ...applyExceptions({ dir: compDir, ruleId: RULE_ID, violations: local, rel }),
    );
  }

  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-component-state-vocab — ${componentFiles.length} component file(s) checked; state vocabulary consistent.\n`,
    );
    return 0;
  }

  process.stderr.write(
    `❌ verify-component-state-vocab: ${violations.length} violation(s)\n\n`,
  );
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write(
    `\nPer COMPONENT_CREATION.yaml.state_vocabulary, components consume shared state classes only.\n` +
      `Allowed: \`state-hover-contained\`, \`state-focus-visible\`, etc. (defined in src/styles/states.css).\n` +
      `Forbidden: direct \`hover:\` / \`focus:\` / \`active:\` Tailwind variants in component sources.\n` +
      `Cross-variant consistency: all entries within a cva group MUST share the same state-class per state.\n`,
  );
  return 1;
}

function check_component_design_locked(srcRoot = "src") {
  const RULE_ID = "verify-component-design-locked";
  const SRC_ROOT = srcRoot;
  const REPO_ROOT = process.cwd();
  const absRoot = join(REPO_ROOT, SRC_ROOT);

  const LOCK_MARKER_REGEX = /<!--\s*design-locked:\s*\d{4}-\d{2}-\d{2}(\s+by:(user|agent))?\s*-->/;

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-component-design-locked — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  const componentFolders = discoverComponents(absRoot).map((c) => c.dir);

  if (componentFolders.length === 0) {
    process.stdout.write(
      `✅ verify-component-design-locked — no design-system components found under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
    );
    return 0;
  }

  const violations = [];

  function firstCommitIso(filePath) {
    try {
      const iso = execSync(
        `git log --diff-filter=A --format=%aI -- ${JSON.stringify(filePath)}`,
        { cwd: REPO_ROOT, stdio: ["ignore", "pipe", "ignore"] },
      )
        .toString()
        .trim()
        .split("\n")
        .filter(Boolean)
        .pop();
      return iso || null;
    } catch {
      return null;
    }
  }

  function checkFolder(folder, rel, name) {
    const local = [];
    const designPath = join(folder, "__specs__", "design.md");
    const designRel = relative(REPO_ROOT, designPath);

    if (!existsSync(designPath)) {
      local.push(
        `${rel}: missing __specs__/design.md (required before any ${name}.tsx is committed)`,
      );
      return local;
    }

    let content;
    try {
      content = readFileSync(designPath, "utf8");
    } catch (e) {
      local.push(`${designRel}: read error — ${e.message}`);
      return local;
    }

    if (!LOCK_MARKER_REGEX.test(content)) {
      local.push(
        `${designRel}: missing lock marker \`<!-- design-locked: YYYY-MM-DD -->\` (user inserts after approving; spec-writer never self-signs)`,
      );
      return local;
    }

    const sourceTsx = join(folder, `${name}.tsx`);
    const designAddedAt = firstCommitIso(designPath);
    const sourceAddedAt = firstCommitIso(sourceTsx);

    if (designAddedAt && sourceAddedAt) {
      if (new Date(sourceAddedAt).getTime() < new Date(designAddedAt).getTime()) {
        local.push(
          `${rel}: ${name}.tsx (first committed ${sourceAddedAt}) precedes ${designRel} (first committed ${designAddedAt}). Code shipped before design — violates phase order.`,
        );
      }
    }
    return local;
  }

  for (const folder of componentFolders) {
    const rel = relative(REPO_ROOT, folder);
    const name = basename(folder);
    const local = checkFolder(folder, rel, name);
    violations.push(
      ...applyExceptions({ dir: folder, ruleId: RULE_ID, violations: local, rel }),
    );
  }

  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-component-design-locked — ${componentFolders.length} component(s) checked; all design-locked.\n`,
    );
    return 0;
  }

  process.stderr.write(
    `❌ verify-component-design-locked: ${violations.length} violation(s)\n\n`,
  );
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write(
    `\nPer COMPONENT_CREATION.yaml.phases, source MUST NOT land before design.md is locked.\n` +
      `Template: ~/.claude/standards/templates/component-design.md.template\n` +
      `User inserts the lock marker after approving the design.\n`,
  );
  return 1;
}

function check_component_spec(srcRoot = "src") {
  const RULE_ID = "verify-component-spec";

  const SRC_ROOT = srcRoot;
  const REPO_ROOT = process.cwd();
  const absRoot = join(REPO_ROOT, SRC_ROOT);

  const REQUIRED_TOP_LEVEL = [
    "spec_version", "component", "package", "folder", "status", "api_shape",
  ];

  const VALID_API_SHAPES = new Set(["MUI", "DaisyUI", "shadcn", "custom-justified"]);
  const VALID_STATUS = new Set(["draft", "locked"]);

  const REQUIRED_BLOCKS = [
    "public_api",
    "tokens_consumed",
    "state_classes_consumed",
    "test_coverage",
  ];
  const REQUIRED_BLOCKS_WITH_VARIANTS = REQUIRED_BLOCKS;
  const REQUIRED_BLOCKS_WITHOUT_VARIANTS = REQUIRED_BLOCKS;

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-component-spec — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  const specPaths = discoverSpeccedComponents(absRoot).map((c) => c.specPath);

  if (specPaths.length === 0) {
    process.stdout.write(
      `✅ verify-component-spec — no component spec.yaml found under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
    );
    return 0;
  }

  const violations = [];

  function isMissingOrEmpty(value) {
    if (value === undefined || value === null) return true;
    if (typeof value === "string" && value.trim().length === 0) return true;
    if (Array.isArray(value) && value.length === 0) return true;
    if (typeof value === "object" && Object.keys(value).length === 0) return true;
    return false;
  }

  function collectSpecViolations(specPath, rel) {
    const local = [];
    // Route the structured spec.yaml read through loadSpec (pass the __specs__ dir).
    const specRes = loadSpec(dirname(specPath));
    if (!specRes.ok) {
      if (/yaml package not available/.test(specRes.error || "")) {
        local.push(`${rel}: cannot resolve \`yaml\` package. Install it: pnpm add -D yaml`);
      } else {
        local.push(`${rel}: YAML parse error — ${specRes.error}`);
      }
      return local;
    }
    const doc = specRes.value;
    if (!doc || typeof doc !== "object") {
      local.push(`${rel}: spec is empty or not a YAML object`);
      return local;
    }

    if (doc.tier === "composite" || doc.tier === "page") return local;

    for (const field of REQUIRED_TOP_LEVEL) {
      if (isMissingOrEmpty(doc[field])) {
        local.push(`${rel}: missing required top-level field \`${field}\``);
      }
    }

    if (doc.api_shape && !VALID_API_SHAPES.has(doc.api_shape)) {
      local.push(
        `${rel}: api_shape="${doc.api_shape}" is not one of [${[...VALID_API_SHAPES].join(", ")}]`,
      );
    }
    if (doc.status && !VALID_STATUS.has(doc.status)) {
      local.push(
        `${rel}: status="${doc.status}" is not one of [${[...VALID_STATUS].join(", ")}]`,
      );
    }

    const hasVariants = doc.has_variants !== false;
    const required = hasVariants
      ? REQUIRED_BLOCKS_WITH_VARIANTS
      : REQUIRED_BLOCKS_WITHOUT_VARIANTS;

    for (const block of required) {
      if (isMissingOrEmpty(doc[block])) {
        local.push(
          `${rel}: missing required block \`${block}\` (or it is empty)` +
            (!hasVariants ? "" : " — set top-level has_variants:false if this component genuinely has no variants"),
        );
      }
    }

    if (doc.touch_target_minima && !isMissingOrEmpty(doc.touch_target_minima)) {
      if (!doc.touch_target_minima.wcag_sc || !doc.touch_target_minima.min_px) {
        local.push(`${rel}: touch_target_minima must declare \`wcag_sc\` and \`min_px\``);
      }
    }

    if (Array.isArray(doc.wcag_aa_contrast_pairs)) {
      for (const pair of doc.wcag_aa_contrast_pairs) {
        if (pair && pair.passes === false && isMissingOrEmpty(pair.deviation)) {
          const combo = pair.combo || "<unknown>";
          local.push(
            `${rel}: contrast pair \`${combo}\` fails AA but lacks \`deviation:\` justification`,
          );
        }
      }
    }
    return local;
  }

  for (const specPath of specPaths) {
    const rel = relative(REPO_ROOT, specPath);
    const compDir = dirname(dirname(specPath));
    const local = collectSpecViolations(specPath, rel);
    violations.push(
      ...applyExceptions({ dir: compDir, ruleId: RULE_ID, violations: local, rel }),
    );
  }

  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-component-spec — ${specPaths.length} spec(s) checked; all required blocks present.\n`,
    );
    return 0;
  }

  process.stderr.write(
    `❌ verify-component-spec: ${violations.length} violation(s)\n\n`,
  );
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write(
    `\nPer COMPONENT_CREATION.yaml.component_spec_schema, every required block must be present.\n` +
      `Template: ~/.claude/standards/templates/component-spec.md.template\n`,
  );
  return 1;
}

function check_component_research_cited(srcRoot = "src") {
  const RULE_ID = "verify-component-research-cited";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const YELLOW = "\x1b[33m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const NON_EMPTY_THRESHOLD_BYTES = 500;
  const TEMPLATE_RESIDUE_PATTERNS = [
    /<PLACEHOLDER>/,
    /<ComponentName>/,
    /<one-line>/,
    /<URL or "n\/a">/,
  ];

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-research-cited:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-research-cited${RESET} — ${msg}\n`);
  }

  function warn(msg) {
    process.stdout.write(`${YELLOW}⚠  verify-component-research-cited:${RESET} ${msg}\n`);
  }

  function findUiRoots(srcRoot) {
    return fs.existsSync(srcRoot) ? [srcRoot] : [];
  }

  function listComponentFolders(root) {
    return discoverComponents(root).map((c) => c.dir);
  }

  function isNonEmptyContentful(filePath) {
    if (!fs.existsSync(filePath)) return false;
    const stat = fs.statSync(filePath);
    if (stat.size < NON_EMPTY_THRESHOLD_BYTES) return false;
    const text = fs.readFileSync(filePath, "utf8");
    const residueHits = TEMPLATE_RESIDUE_PATTERNS.filter((re) => re.test(text)).length;
    return residueHits <= 1;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const uiRoots = findUiRoots(srcRootAbs);
  if (uiRoots.length === 0) {
    ok(`no design-system components found under ${arg} (components/ui, components/, or feature-located components/); nothing to verify.`);
    return 0;
  }

  const violations = [];
  let componentsScanned = 0;

  for (const uiRoot of uiRoots) {
    for (const componentFolder of listComponentFolders(uiRoot)) {
      const specsDir = path.join(componentFolder, "__specs__");
      const designPath = path.join(specsDir, "design.md");
      const researchPath = path.join(specsDir, "research.md");

      if (!fs.existsSync(designPath)) continue;

      componentsScanned++;

      if (!fs.existsSync(researchPath)) {
        violations.push({
          folder: componentFolder,
          rule: "research.md missing",
          fix: `create ${path.relative(process.cwd(), researchPath)} from ~/.claude/standards/templates/research.md.template`,
        });
        continue;
      }

      if (!isNonEmptyContentful(researchPath)) {
        violations.push({
          folder: componentFolder,
          rule: "research.md exists but appears empty or template-residue",
          fix: "fill the template; minimum 500 bytes of real content; remove <PLACEHOLDER> tokens",
        });
        continue;
      }

      const designText = fs.readFileSync(designPath, "utf8");
      if (!/research\.md/i.test(designText)) {
        violations.push({
          folder: componentFolder,
          rule: "design.md does not reference research.md",
          fix: "add a 'see __specs__/research.md' reference (any sentence mentioning research.md)",
        });
      }
    }
  }

  {
    const survivors = applyExceptionsByFolder(violations, RULE_ID, process.cwd());
    violations.length = 0;
    violations.push(...survivors);
  }

  if (violations.length === 0) {
    if (componentsScanned === 0) {
      ok(`no components with design.md found under ${arg}; nothing to verify.`);
    } else {
      ok(`${componentsScanned} component(s) checked; all cite research.md.`);
    }
    return 0;
  }

  process.stderr.write(`${RED}❌ verify-component-research-cited:${RESET} ${violations.length} violation(s)\n\n`);
  for (const v of violations) {
    process.stderr.write(`  ${path.relative(process.cwd(), v.folder)}:\n`);
    process.stderr.write(`    rule: ${v.rule}\n`);
    process.stderr.write(`    fix:  ${v.fix}\n\n`);
  }
  process.stderr.write(
    `${DIM}Per COMPONENT_CREATION.yaml.phases.0_research, every component's design phase requires a Phase 0 research.md. Template at ~/.claude/standards/templates/research.md.template${RESET}\n`,
  );
  return 1;
}

function check_component_design_self_lock_eligible(srcRoot = "src") {
  const RULE_ID = "verify-component-design-self-lock-eligible";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const REQUIRED_DESIGN_HEADINGS = [
    "## Anatomy diagram",
    "## State matrix",
    "## Token bindings",
    "## ARIA pattern",
    "## Keyboard interactions",
    "## Responsive strategy",
    "## Forced-colors strategy",
    "## Reduced-motion strategy",
    "## RTL strategy",
    "## Edge cases",
    "## Composition rules",
  ];
  const REQUIRED_DESIGN_SUBSECTIONS = [
    "### Cross-variant consistency rule",
  ];

  const APG_PATTERN_URL_REGEX =
    /https:\/\/www\.w3\.org\/WAI\/ARIA\/apg\/patterns\/[a-z0-9-]+\/?/;
  const NA_PATTERN_REGEX = /n\/a\s*—\s*[^\s]/i;
  const PLACEHOLDER_PATTERNS = [
    /<PLACEHOLDER>/,
    /<ComponentName>/,
    /<one-line>/,
    /<bg-token\s*\+\s*fg-token>/,
    /<part_name>/,
    /<variant>\.<color>\.<size>/,
  ];
  const VAGUE_TOKENS = [
    /\bTBD\b/,
    /\btbd\b/,
    /\bTODO\b/,
    /\bTODO[_-]?LATER\b/i,
    /\bTODO[_-]?FIX\b/i,
    /\bWIP\b/,
    /\bFIXME\b/,
    /\bXXX\b/,
    /\bHACK\b/,
  ];
  const STATE_MATRIX_HOLES = [
    /…/,
    /\.{3,}/,
    /\bN\/A\b\s*—\s*$/m,
    /\betc\.?/i,
    /\band so on\b/i,
    /\bsimilar\b/i,
    /\(rest as above\)/i,
  ];

  const BY_AGENT_MARKER_REGEX = /<!--\s*design-locked:\s*(\d{4}-\d{2}-\d{2})\s+by:agent\s*-->/;
  const BY_USER_MARKER_REGEX = /<!--\s*design-locked:\s*(\d{4}-\d{2}-\d{2})\s+by:user\s*-->/;

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-design-self-lock-eligible:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-design-self-lock-eligible${RESET} — ${msg}\n`);
  }

  function extractSection(designText, heading) {
    const lines = designText.split(/\r?\n/);
    const idx = lines.findIndex((l) => l.trim() === heading);
    if (idx === -1) return null;
    const headingLevel = heading.match(/^#+/)?.[0].length ?? 2;
    const stopRe = new RegExp(`^#{1,${headingLevel}}\\s`);
    const collected = [];
    for (let i = idx + 1; i < lines.length; i++) {
      if (stopRe.test(lines[i])) break;
      collected.push(lines[i]);
    }
    return collected.join("\n").trim();
  }

  function findUiRoots(srcRoot) {
    return fs.existsSync(srcRoot) ? [srcRoot] : [];
  }

  function listComponentFolders(root) {
    return discoverComponents(root).map((c) => c.dir);
  }

  function checkDesignEligibility(designText, specText, hasResearch) {
    const violations = [];

    for (const heading of REQUIRED_DESIGN_HEADINGS) {
      const section = extractSection(designText, heading);
      if (section === null) {
        violations.push(`design.md missing required heading: "${heading}"`);
        continue;
      }
      if (section.length < 20) {
        violations.push(`design.md "${heading}" section is empty or stub (<20 chars body)`);
        continue;
      }
      for (const re of PLACEHOLDER_PATTERNS) {
        if (re.test(section)) {
          violations.push(
            `design.md "${heading}" still contains template placeholder pattern: ${re}`,
          );
          break;
        }
      }
      for (const re of VAGUE_TOKENS) {
        if (re.test(section)) {
          violations.push(`design.md "${heading}" contains vague token: ${re}`);
          break;
        }
      }
    }

    for (const sub of REQUIRED_DESIGN_SUBSECTIONS) {
      const section = extractSection(designText, sub);
      if (section === null || section.length < 20) {
        violations.push(`design.md missing or empty subsection: "${sub}"`);
      }
    }

    const stateMatrix = extractSection(designText, "## State matrix");
    if (stateMatrix !== null) {
      for (const re of STATE_MATRIX_HOLES) {
        if (re.test(stateMatrix)) {
          violations.push(
            `design.md state matrix contains hole pattern: ${re} — must be exhaustive (no '…', 'etc.', or empty rows)`,
          );
          break;
        }
      }
    }

    const ariaSection = extractSection(designText, "## ARIA pattern");
    if (ariaSection !== null) {
      const hasApgUrl = APG_PATTERN_URL_REGEX.test(ariaSection);
      const hasNaJustification = NA_PATTERN_REGEX.test(ariaSection);
      if (!hasApgUrl && !hasNaJustification) {
        violations.push(
          `design.md ARIA pattern section: must contain a real WAI-ARIA APG URL OR explicit "n/a — <reason>"`,
        );
      }
    }

    const edgeCases = extractSection(designText, "## Edge cases");
    if (edgeCases !== null) {
      const tableRows = edgeCases
        .split(/\r?\n/)
        .filter((l) => /^\s*\|/.test(l) && !/^\s*\|\s*-+/.test(l) && !/Case\s*\|\s*Handling/i.test(l));
      if (tableRows.length < 2) {
        violations.push(
          `design.md Edge cases: needs at least 2 substantive rows (found ${tableRows.length})`,
        );
      }
      for (const row of tableRows) {
        const cells = row.split("|").map((c) => c.trim()).filter((c) => c.length > 0);
        if (cells.length < 2 || cells.some((c) => c.length === 0)) {
          violations.push(
            `design.md Edge cases row missing case or handling: "${row.trim().slice(0, 60)}..."`,
          );
        }
      }
    }

    if (!/research\.md/i.test(designText)) {
      violations.push(`design.md does not reference research.md (Phase 0 citation required)`);
    }

    const crossVariantSection = extractSection(designText, "### Cross-variant consistency rule");
    if (crossVariantSection !== null && !/state-/.test(crossVariantSection)) {
      violations.push(
        `design.md Cross-variant consistency rule must name concrete state-* classes (e.g. state-hover-contained)`,
      );
    }

    if (specText !== null) {
      for (const re of VAGUE_TOKENS) {
        if (re.test(specText)) {
          violations.push(`spec.yaml contains vague token: ${re}`);
          break;
        }
      }
      const placeholderUnclosed = /<\w[\w\s\-|.]*>/g;
      const placeholderMatches = specText.match(placeholderUnclosed) ?? [];
      const realPlaceholders = placeholderMatches.filter(
        (m) =>
          !/^<\d+px/.test(m) &&
          !/^<svg/.test(m) &&
          !/^<button/.test(m) &&
          !/^<a\s/.test(m) &&
          !/^<\/?[a-zA-Z]+\s*>$/.test(m),
      );
      if (realPlaceholders.length > 0) {
        violations.push(
          `spec.yaml contains ${realPlaceholders.length} placeholder(s): ${realPlaceholders.slice(0, 3).join(", ")}`,
        );
      }

      const contrastSectionMatch = specText.match(/wcag_aa_contrast_pairs:\s*([\s\S]*?)(?=^\w|^# |\Z)/m);
      if (contrastSectionMatch) {
        const contrastBlock = contrastSectionMatch[1];
        const passingFalseEntries = contrastBlock.split(/\n\s*-\s+combo:/g);
        for (const entry of passingFalseEntries) {
          if (/passes:\s*false/.test(entry) && !/deviation:\s*\S/.test(entry)) {
            violations.push(
              `spec.yaml contrast_pairs entry with passes:false missing non-empty deviation:`,
            );
            break;
          }
        }
      }
    }

    if (!hasResearch) {
      violations.push(`research.md (Phase 0) missing — required before by:agent self-lock`);
    }

    return violations;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const uiRoots = findUiRoots(srcRootAbs);
  if (uiRoots.length === 0) {
    ok(`no src/components/ui/ folder under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];
  let componentsScanned = 0;
  let byAgentMarkers = 0;
  let byUserMarkers = 0;

  for (const uiRoot of uiRoots) {
    for (const componentFolder of listComponentFolders(uiRoot)) {
      const specsDir = path.join(componentFolder, "__specs__");
      const designPath = path.join(specsDir, "design.md");
      const researchPath = path.join(specsDir, "research.md");

      if (!fs.existsSync(designPath)) continue;
      componentsScanned++;

      const designText = fs.readFileSync(designPath, "utf8");
      const hasAgent = BY_AGENT_MARKER_REGEX.test(designText);
      const hasUser = BY_USER_MARKER_REGEX.test(designText);

      if (hasUser) byUserMarkers++;
      if (hasAgent) byAgentMarkers++;

      if (!hasAgent) continue;

      const specText = specMachineText(specsDir);
      const hasResearch = fs.existsSync(researchPath) && fs.statSync(researchPath).size > 500;

      const violations = checkDesignEligibility(designText, specText, hasResearch);
      if (violations.length > 0) {
        allViolations.push({
          folder: path.relative(process.cwd(), componentFolder),
          violations,
        });
      }
    }
  }

  {
    const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
    allViolations.length = 0;
    allViolations.push(...survivors);
  }

  if (allViolations.length === 0) {
    if (componentsScanned === 0) {
      ok(`no components with design.md under ${arg}; nothing to verify.`);
    } else {
      ok(
        `${componentsScanned} component(s) checked; ${byUserMarkers} by:user, ${byAgentMarkers} by:agent — all eligible.`,
      );
    }
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-design-self-lock-eligible:${RESET} ${allViolations.length} component(s) with ineligible by:agent self-lock\n\n`,
  );
  for (const a of allViolations) {
    process.stderr.write(`  ${a.folder}:\n`);
    for (const v of a.violations) {
      process.stderr.write(`    - ${v}\n`);
    }
    process.stderr.write("\n");
  }
  process.stderr.write(
    `${DIM}Either: (a) fix every violation listed and re-run, OR (b) replace the by:agent marker with by:user (this verifier skips by:user markers entirely).${RESET}\n`,
  );
  return 1;
}

function check_component_research_depth(srcRoot = "src") {
  const RULE_ID = "verify-component-research-depth";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const DEPTH_BUDGETS_BYTES = {
    light: 500,
    medium: 4000,
    thorough: 12000,
  };

  const LIBRARY_DOC_DOMAINS = [
    "ui.shadcn.com",
    "shadcn-ui.com",
    "mui.com",
    "daisyui.com",
    "radix-ui.com",
  ];

  const APG_URL_REGEX = /https:\/\/www\.w3\.org\/WAI\/ARIA\/apg\/patterns\/[a-z0-9-]+\/?/g;
  const ANY_URL_REGEX = /https?:\/\/[^\s)>\]"']+/g;

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-research-depth:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-research-depth${RESET} — ${msg}\n`);
  }

  function deriveDepth(stakes, coverage) {
    const s = (stakes ?? "standard").toLowerCase();
    const c = (coverage ?? "full").toLowerCase();
    const matrix = {
      full_internal: "light",
      full_standard: "light",
      full_brand: "medium",
      partial_internal: "medium",
      partial_standard: "medium",
      partial_brand: "thorough",
      none_internal: "medium",
      none_standard: "thorough",
      none_brand: "thorough",
    };
    return matrix[`${c}_${s}`] ?? "medium";
  }

  function findSpecFolders(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".") || e.name.startsWith("_")) continue;
        const full = path.join(dir, e.name);
        if (
          fs.existsSync(path.join(full, "__specs__", "research.md")) &&
          full.split(path.sep).includes("components")
        ) {
          found.push(full);
          continue;
        }
        queue.push(full);
      }
    }
    return found;
  }

  function classifyCoverage(researchText) {
    const m = researchText.match(/library coverage\*\*:\s*([a-z]+)/i);
    if (m) {
      const c = m[1].toLowerCase();
      if (["full", "partial", "none"].includes(c)) return c;
    }
    return "full";
  }

  function classifySurveyMode(researchText) {
    const m = researchText.match(/domain survey trigger\*\*:\s*([a-z\- ]+)/i);
    if (!m) return "skip";
    const v = m[1].trim().toLowerCase();
    if (v.startsWith("skip")) return "skip";
    if (v.startsWith("brand")) return "brand-language-only";
    if (v.startsWith("targeted")) return "targeted-gaps";
    if (v.startsWith("mandatory")) return "mandatory-full";
    return v;
  }

  function stripTemplateResidue(text) {
    let stripped = text;
    const residuePatterns = [
      /<PLACEHOLDER>/g,
      /<ComponentName>/g,
      /<one-line>/g,
      /<URL or "n\/a">/g,
      /<URL>/g,
    ];
    for (const re of residuePatterns) {
      stripped = stripped.replace(re, "");
    }
    return stripped;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const folders = findSpecFolders(srcRootAbs);
  if (folders.length === 0) {
    ok(`no components with research.md under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];

  for (const folder of folders) {
    const specsDir = path.join(folder, "__specs__");
    const researchPath = path.join(specsDir, "research.md");
    const designPath = path.join(specsDir, "design.md");

    if (!fs.existsSync(researchPath)) continue;

    let spec = null;
    if (specFileExists(specsDir)) {
      const specRes = loadSpec(specsDir);
      spec = specRes.ok ? specRes.value : null;
    }

    const stakes = spec?.stakes ?? "standard";
    const researchText = fs.readFileSync(researchPath, "utf8");
    const coverage = classifyCoverage(researchText);
    const surveyMode = classifySurveyMode(researchText);
    const depth = deriveDepth(stakes, coverage);
    const minBytes = DEPTH_BUDGETS_BYTES[depth];

    const strippedSize = stripTemplateResidue(researchText).length;
    if (strippedSize < minBytes) {
      allViolations.push({
        folder,
        rule: `research.md too thin for derived depth ${depth} (stakes=${stakes}, coverage=${coverage}); needs ≥ ${minBytes} bytes after stripping template residue, has ${strippedSize}`,
      });
    }

    const urls = (researchText.match(ANY_URL_REGEX) ?? []).filter(
      (u) => !u.includes("PLACEHOLDER") && !u.includes("example.com"),
    );
    const hasLibraryDoc = urls.some((u) =>
      LIBRARY_DOC_DOMAINS.some((d) => u.includes(d)),
    );

    if (coverage !== "none" && !hasLibraryDoc) {
      allViolations.push({
        folder,
        rule: `research.md has no URL pointing at shadcn/MUI/DaisyUI library docs; coverage=${coverage} implies at least one library doc citation`,
      });
    }

    if (surveyMode !== "skip" && surveyMode !== "brand-language-only") {
      const nonLibraryUrls = urls.filter(
        (u) => !LIBRARY_DOC_DOMAINS.some((d) => u.includes(d)),
      );
      if (nonLibraryUrls.length < 1) {
        allViolations.push({
          folder,
          rule: `research.md domain survey mode is "${surveyMode}" but no non-library URLs cited; survey not actually performed`,
        });
      }
    }

    if (fs.existsSync(designPath)) {
      const designText = fs.readFileSync(designPath, "utf8");
      const apgInDesign = [...designText.matchAll(APG_URL_REGEX)].map((m) => m[0]);
      const apgInResearch = [...researchText.matchAll(APG_URL_REGEX)].map((m) => m[0]);
      for (const url of apgInDesign) {
        const normalized = url.replace(/\/$/, "");
        const cited = apgInResearch.some(
          (r) => r.replace(/\/$/, "") === normalized,
        );
        if (!cited) {
          allViolations.push({
            folder,
            rule: `design.md cites APG pattern ${url} but research.md does not — APG choice must be supported by Phase 0 evidence`,
          });
        }
      }
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(`${folders.length} component(s) checked; research depth + URL citations valid.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-research-depth:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Phase 0 depth is derived from coverage × stakes; insufficient bytes or missing URL citations mean the research did not actually run.${RESET}\n`,
  );
  return 1;
}

function check_component_spec_matrix_completeness(srcRoot = "src") {
  const RULE_ID = "verify-component-spec-matrix-completeness";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-spec-matrix-completeness:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-spec-matrix-completeness${RESET} — ${msg}\n`);
  }

  function findUiRoots(srcRoot) {
    return fs.existsSync(srcRoot) ? [srcRoot] : [];
  }

  function listComponentFolders(root) {
    return discoverComponents(root).map((c) => c.dir);
  }

  function extractEnumValues(typeStr) {
    if (typeof typeStr !== "string") return null;
    const m = typeStr.match(/enum\[([^\]]+)\]/);
    if (!m) return null;
    return m[1]
      .split(",")
      .map((s) => s.trim().replace(/^["']|["']$/g, ""))
      .filter((s) => s.length > 0);
  }

  function cartesian(arrays) {
    if (arrays.length === 0) return [[]];
    const [first, ...rest] = arrays;
    const restCombos = cartesian(rest);
    const out = [];
    for (const v of first) {
      for (const r of restCombos) {
        out.push([v, ...r]);
      }
    }
    return out;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const uiRoots = findUiRoots(srcRootAbs);
  if (uiRoots.length === 0) {
    ok(`no src/components/ui/ folder under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];
  let componentsScanned = 0;

  for (const uiRoot of uiRoots) {
    for (const componentFolder of listComponentFolders(uiRoot)) {
      const specsDir = path.join(componentFolder, "__specs__");
      if (!specFileExists(specsDir)) continue;

      const specRes = loadSpec(specsDir);
      if (!specRes.ok) {
        allViolations.push({
          folder: componentFolder,
          rule: `spec.yaml parse error: ${specRes.error}`,
        });
        continue;
      }
      const spec = specRes.value;

      const tier = spec?.tier;
      if (tier && tier !== "atomic") continue;
      componentsScanned++;

      const props = spec?.public_api?.props ?? {};
      const axes = ["variant", "color", "size"];
      const enums = {};
      for (const axis of axes) {
        const values = extractEnumValues(props[axis]?.type);
        if (values && values.length > 0) {
          enums[axis] = values;
        }
      }

      const axesPresent = Object.keys(enums);
      if (axesPresent.length === 0) continue;

      const rest = spec?.interaction_states?.rest ?? {};
      const restKeys = new Set(Object.keys(rest));
      if (restKeys.size === 0) continue;

      const sampleKey = Array.from(restKeys)[0];
      const sampleParts = sampleKey.split(".").length;
      const usesSizeAxis = sampleParts >= 3;

      const cartesianAxes = usesSizeAxis ? axesPresent : axesPresent.filter((a) => a !== "size");
      const arrays = cartesianAxes.map((a) => enums[a] ?? [""]);
      const expectedCombos = cartesian(arrays).map((combo) => combo.join("."));

      const missing = expectedCombos.filter((c) => !restKeys.has(c));
      if (missing.length > 0) {
        allViolations.push({
          folder: componentFolder,
          rule: `interaction_states.rest missing ${missing.length} combination(s) of declared enum values: ${missing.slice(0, 5).join(", ")}${missing.length > 5 ? "..." : ""}`,
        });
      }

      const expectedSet = new Set(expectedCombos);
      const extras = Array.from(restKeys).filter((k) => !expectedSet.has(k));
      if (extras.length > 0) {
        allViolations.push({
          folder: componentFolder,
          rule: `interaction_states.rest has ${extras.length} key(s) NOT in declared enum values (typo or stale entry?): ${extras.slice(0, 5).join(", ")}${extras.length > 5 ? "..." : ""}`,
        });
      }
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    if (componentsScanned === 0) {
      ok(`no atomic specs found under ${arg}; nothing to verify.`);
    } else {
      ok(`${componentsScanned} atomic spec(s) checked; props ↔ state matrix complete.`);
    }
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-spec-matrix-completeness:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Every Cartesian product of declared enum values for variant/color/size must appear in interaction_states.rest.${RESET}\n`,
  );
  return 1;
}

function check_component_stakes_honest(srcRoot = "src") {
  const RULE_ID = "verify-component-stakes-honest";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-stakes-honest:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-stakes-honest${RESET} — ${msg}\n`);
  }

  function globToRegex(glob) {
    const escaped = glob
      .replace(/[.+^${}()|[\]\\]/g, "\\$&")
      .replace(/\*\*/g, "::DOUBLESTAR::")
      .replace(/\*/g, "[^/]*")
      .replace(/::DOUBLESTAR::/g, ".*");
    return new RegExp(`^${escaped}$`);
  }

  function readAutonomy() {
    const yaml = loadYaml();
    if (!yaml) return null;
    let dir = process.cwd();
    for (let i = 0; i < 20; i++) {
      const candidate = path.join(dir, ".standards", "autonomy.yaml");
      if (fs.existsSync(candidate)) {
        try {
          return yaml.parse(fs.readFileSync(candidate, "utf8"));
        } catch {
          return null;
        }
      }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
    return null;
  }

  function findSpecFolders(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".") || e.name.startsWith("_")) continue;
        const full = path.join(dir, e.name);
        if (
          specFileExists(path.join(full, "__specs__")) &&
          full.split(path.sep).includes("components")
        ) {
          found.push(full);
          continue;
        }
        queue.push(full);
      }
    }
    return found;
  }

  function matchesAnyGlob(relPath, globs) {
    if (!Array.isArray(globs)) return false;
    return globs.some((g) => {
      if (typeof g !== "string" || g.length === 0) return false;
      return globToRegex(g).test(relPath);
    });
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const autonomy = readAutonomy();
  const brandSurfaces = autonomy?.brand_surfaces ?? [];
  const internalSurfaces = autonomy?.internal_surfaces ?? [];

  const folders = findSpecFolders(srcRootAbs);
  if (folders.length === 0) {
    ok(`no spec folders under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];
  const repoRoot = (() => {
    let d = process.cwd();
    for (let i = 0; i < 20; i++) {
      if (fs.existsSync(path.join(d, ".git")) || fs.existsSync(path.join(d, "package.json"))) return d;
      const p = path.dirname(d);
      if (p === d) break;
      d = p;
    }
    return process.cwd();
  })();

  for (const folder of folders) {
    const specRes = loadSpec(path.join(folder, "__specs__"));
    if (!specRes.ok) continue;
    const spec = specRes.value;

    const declaredStakes = spec?.stakes;
    if (!declaredStakes) continue;

    const relPath = path.relative(repoRoot, folder).replace(/\\/g, "/");
    const matchesBrand = matchesAnyGlob(relPath, brandSurfaces);
    const matchesInternal = matchesAnyGlob(relPath, internalSurfaces);

    if (declaredStakes === "internal" && matchesBrand) {
      allViolations.push({
        folder,
        rule: `spec.yaml stakes="internal" but folder ${relPath} matches autonomy.yaml.brand_surfaces glob`,
      });
    }
    if (declaredStakes === "brand" && matchesInternal) {
      allViolations.push({
        folder,
        rule: `spec.yaml stakes="brand" but folder ${relPath} matches autonomy.yaml.internal_surfaces glob`,
      });
    }
    if (declaredStakes === "standard" && matchesBrand) {
      allViolations.push({
        folder,
        rule: `spec.yaml stakes="standard" but folder ${relPath} matches autonomy.yaml.brand_surfaces glob; either upgrade to "brand" or remove the glob entry`,
      });
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(`${folders.length} spec(s) checked; declared stakes match folder placement.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-stakes-honest:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Either: (a) update spec.yaml.stakes to match the folder placement; OR (b) update autonomy.yaml's brand_surfaces / internal_surfaces globs to reflect the placement intent.${RESET}\n`,
  );
  return 1;
}

function check_component_storybook_docs(srcRoot = "src") {
  const RULE_ID = "verify-component-storybook-docs";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const REQUIRED_USAGE_SECTIONS = [
    /<Meta[^>]*\bname=["']Usage["']/,
    /^#\s+\w+\s+Usage\s*$/m,
    /^##\s+Installation\s*$/m,
    /^##\s+Import\s*$/m,
    /^##\s+Basic\s+Usage\s*$/m,
    /^##\s+Props\s*$/m,
    /^##\s+Examples\s*$/m,
    /^##\s+Accessibility\s*$/m,
    /^##\s+Design\s+System\s+Integration\s*$/m,
  ];
  const REQUIRED_USAGE_SECTION_NAMES = [
    '<Meta … name="Usage"> (the doc entry must be named Usage — distinct from README)',
    "# <Name> Usage (H1)",
    "## Installation",
    "## Import",
    "## Basic Usage",
    "## Props",
    "## Examples (with H3 subsections)",
    "## Accessibility",
    "## Design System Integration",
  ];

  const REQUIRED_README_SECTIONS = [
    /<Meta[^>]*\bname=["']README["']/,
    /^#\s+\w+\s*$/m,
    /\*\*What it is\b/im,
  ];
  const REQUIRED_README_SECTION_NAMES = [
    '<Meta … name="README"> (the doc entry must be named README — distinct from Usage)',
    "# <Name> (H1 = the bare component name)",
    "**What it is —** … (explainer of what the component IS)",
  ];

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-storybook-docs${RESET} — ${msg}\n`);
  }

  function findUiRoots(srcRoot) {
    return fs.existsSync(srcRoot) ? [srcRoot] : [];
  }

  function listComponentFolders(root) {
    return discoverComponents(root).map((c) => c.dir);
  }

  function checkComponent(componentFolder) {
    const violations = [];
    const name = path.basename(componentFolder);
    const storiesDir = path.join(componentFolder, "__stories__");
    const storiesPath = path.join(storiesDir, `${name}.stories.tsx`);
    const readmeMdxPath = path.join(storiesDir, `${name}.readme.mdx`);
    const usageMdxPath = path.join(storiesDir, `${name}.usage.mdx`);
    const typesPath = path.join(componentFolder, "types.ts");

    if (!fs.existsSync(storiesPath)) {
      return violations;
    }

    const storiesText = fs.readFileSync(storiesPath, "utf8");

    if (!/tags:\s*\[\s*['"]autodocs['"]\s*\]/.test(storiesText)) {
      violations.push({
        file: `${name}.stories.tsx`,
        rule: "Meta must include tags: ['autodocs'] — required to render the Docs view prop table",
      });
    }

    if (!/export\s+const\s+Changelog\b/.test(storiesText)) {
      violations.push({
        file: `${name}.stories.tsx`,
        rule: "missing required Changelog story (`export const Changelog`) — component history belongs here, not in JSDoc/comments/spec.yaml",
      });
    }

    if (!fs.existsSync(readmeMdxPath)) {
      violations.push({
        file: `${name}.readme.mdx`,
        rule: `README MDX missing at ${path.relative(process.cwd(), readmeMdxPath)} — every component ships a README doc entry (distinct from Usage; both required)`,
      });
    } else {
      const readmeText = fs.readFileSync(readmeMdxPath, "utf8");
      REQUIRED_README_SECTIONS.forEach((re, i) => {
        if (!re.test(readmeText)) {
          violations.push({
            file: `${name}.readme.mdx`,
            rule: `missing required element: ${REQUIRED_README_SECTION_NAMES[i]}`,
          });
        }
      });
    }

    if (!fs.existsSync(usageMdxPath)) {
      violations.push({
        file: `${name}.usage.mdx`,
        rule: `Usage MDX missing at ${path.relative(process.cwd(), usageMdxPath)} — every component ships a Usage doc entry (distinct from README; both required)`,
      });
    } else {
      const mdxText = fs.readFileSync(usageMdxPath, "utf8");
      REQUIRED_USAGE_SECTIONS.forEach((re, i) => {
        if (!re.test(mdxText)) {
          violations.push({
            file: `${name}.usage.mdx`,
            rule: `missing required section: ${REQUIRED_USAGE_SECTION_NAMES[i]}`,
          });
        }
      });

      const inlineJsxPreview = /<Canvas[^>]*>[\s\S]*?<\w[A-Za-z]+/m;
      if (inlineJsxPreview.test(mdxText) && !/<Story\s+(of|id)=/.test(mdxText)) {
        violations.push({
          file: `${name}.usage.mdx`,
          rule: "MDX uses inline JSX previews — every preview must reference a story via <Story of={...} /> or <Story id=\"...\" />",
        });
      }
    }

    if (fs.existsSync(typesPath)) {
      const typesText = fs.readFileSync(typesPath, "utf8");
      const ifaceMatch = typesText.match(
        /export\s+(?:interface|type)\s+i\w*Props[^{]*\{([\s\S]*?)^\}/m,
      );
      if (ifaceMatch) {
        const body = ifaceMatch[1];
        const propPattern = /^\s*(\w+)\??\s*:/gm;
        const props = [...body.matchAll(propPattern)].map((m) => ({
          name: m[1],
          idx: m.index ?? 0,
        }));
        for (const { name: propName, idx } of props) {
          if (propName === "extends" || propName === "Omit") continue;
          const lookback = body.slice(Math.max(0, idx - 250), idx);
          const hasJsdoc = /\*\//.test(lookback) && !/^\s*$/.test(lookback);
          if (!hasJsdoc) {
            violations.push({
              file: `types.ts`,
              rule: `prop "${propName}" missing JSDoc — autodocs prop table Description will be empty for this row`,
            });
          }
        }
      }
    }

    return violations.map((v) => ({ ...v, folder: componentFolder }));
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }
  const uiRoots = findUiRoots(srcRootAbs);
  if (uiRoots.length === 0) {
    ok(`no src/components/ui/ folder under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];
  let scanned = 0;
  for (const uiRoot of uiRoots) {
    for (const componentFolder of listComponentFolders(uiRoot)) {
      scanned++;
      const local = checkComponent(componentFolder);
      const rel = path.relative(process.cwd(), componentFolder);
      allViolations.push(
        ...applyExceptions({ dir: componentFolder, ruleId: RULE_ID, violations: local, rel }),
      );
    }
  }

  if (allViolations.length === 0) {
    ok(`${scanned} component(s) checked; autodocs + readme.mdx + usage.mdx + JSDoc all present.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-storybook-docs:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  const byFolder = new Map();
  for (const v of allViolations) {
    const key = path.relative(process.cwd(), v.folder);
    if (!byFolder.has(key)) byFolder.set(key, []);
    byFolder.get(key).push(v);
  }
  for (const [folder, vs] of byFolder) {
    process.stderr.write(`  ${folder}:\n`);
    for (const v of vs) {
      process.stderr.write(`    [${v.file}] ${v.rule}\n`);
    }
    process.stderr.write("\n");
  }
  process.stderr.write(
    `${DIM}Per COMPONENT_DOCS.yaml.readme_mdx + usage_mdx + COMPONENT_CREATION.yaml.phases.4_stories. Every primitive needs autodocs tag + Changelog story + readme.mdx (README entry: what it IS) + usage.mdx (Usage entry: how to use it) + parent-facing JSDoc on every prop.${RESET}\n`,
  );
  return 1;
}

function check_component_spec_vs_source(srcRoot = "src") {
  const RULE_ID = "verify-component-spec-vs-source";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const STATE_CLASS_RE = /\bstate-[a-z0-9-]+\b/g;
  const TOKEN_RE = /var\(\s*(--[a-z0-9-]+)\s*[),]/gi;

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-component-spec-vs-source:${RESET} ${msg}\n`);
    process.exit(1);
  }
  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-component-spec-vs-source${RESET} — ${msg}\n`);
  }

  const srcRootRel = srcRoot;
  if (!srcRootRel) {
    process.stderr.write("usage: verify-component-spec-vs-source.mjs <src-root>\n");
    return 2;
  }

  const componentRecords = discoverComponents(srcRootRel);
  if (componentRecords.length === 0) {
    ok(`no design-system components found under ${srcRootRel} (components/ui, components/, or feature-located components/); nothing to verify.`);
    return 0;
  }

  const shadcnRoot = path.join(srcRootRel, "components", "shadcn");

  const yaml = loadYaml();
  if (!yaml) {
    fail("`yaml` package not installed — needed to parse spec.yaml");
  }

  const violations = [];

  function* walk(dir) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        yield* walk(full);
      } else {
        yield full;
      }
    }
  }

  for (const rec of componentRecords) {
    const comp = rec.name;
    const compDir = rec.dir;
    const specPath = rec.specPath;
    if (!fs.existsSync(specPath)) continue;

    const specRes = loadSpec(path.dirname(specPath));
    if (!specRes.ok) {
      violations.push(
        ...applyExceptions({
          dir: compDir,
          ruleId: RULE_ID,
          violations: [{ comp, kind: "spec_parse", msg: specRes.error }],
          rel: comp,
        }),
      );
      continue;
    }
    const spec = specRes.value;

    const sourceFiles = [];
    for (const entry of walk(compDir)) {
      const rel = path.relative(compDir, entry);
      if (rel.split(path.sep).some((seg) => seg === "__stories__" || seg === "__tests__" || seg === "__specs__")) continue;
      if (entry.endsWith(".tsx") || entry.endsWith(".ts") || entry.endsWith(".css")) {
        sourceFiles.push(entry);
      }
    }
    const candidateBaselines = [];
    if (spec.baseline?.installed_to) {
      const abs = path.resolve(String(spec.baseline.installed_to));
      if (fs.existsSync(abs)) candidateBaselines.push(abs);
    }
    if (fs.existsSync(shadcnRoot)) {
      const a = path.join(shadcnRoot, `${comp.toLowerCase()}.tsx`);
      if (fs.existsSync(a)) candidateBaselines.push(a);
      const b = path.join(
        shadcnRoot,
        `${comp.replace(/([A-Z])/g, "-$1").toLowerCase().replace(/^-/, "")}.tsx`,
      );
      if (fs.existsSync(b)) candidateBaselines.push(b);
    }
    for (const c of candidateBaselines) {
      if (!sourceFiles.includes(c)) sourceFiles.push(c);
    }
    for (const start of [...candidateBaselines]) {
      const baseDir = path.dirname(start);
      const text = fs.readFileSync(start, "utf-8");
      const importRe = /from\s+["']\.\/(.+?)["']/g;
      for (const m of text.matchAll(importRe)) {
        for (const ext of [".tsx", ".ts"]) {
          const target = path.join(baseDir, m[1] + ext);
          if (fs.existsSync(target) && !sourceFiles.includes(target)) {
            sourceFiles.push(target);
          }
        }
      }
    }

    const sourceStateClasses = new Set();
    const sourceTokens = new Set();
    for (const f of sourceFiles) {
      let text = fs.readFileSync(f, "utf-8");
      text = text.replace(/^\s*import\b[\s\S]*?from\s*["'][^"']+["'];?\s*$/gm, "");
      text = text.replace(/^\s*export\b[^\n]*\bfrom\s*["'][^"']+["'];?\s*$/gm, "");
      for (const m of text.matchAll(STATE_CLASS_RE)) sourceStateClasses.add(m[0]);
      for (const m of text.matchAll(TOKEN_RE)) sourceTokens.add(m[1]);
    }

    const specStateClasses = new Set(
      (spec.state_classes_consumed ?? [])
        .filter((s) => typeof s === "string")
        .filter((s) => /^state-[a-z0-9-]+$/.test(s.trim()))
        .map((s) => s.trim()),
    );
    const specTokens = new Set(
      (spec.tokens_consumed ?? [])
        .filter((s) => typeof s === "string")
        .filter((s) => /^--[a-z0-9-]+$/.test(s.trim()))
        .map((s) => s.trim()),
    );

    const specHasNaSentinel = (spec.state_classes_consumed ?? []).some(
      (s) => typeof s === "string" && /^n\/a\b/i.test(s.trim()),
    );

    const missingInSpec = {
      state_classes: [...sourceStateClasses].filter((s) => !specStateClasses.has(s)),
      tokens: [...sourceTokens].filter((t) => !specTokens.has(t)),
    };
    const staleInSpec = {
      state_classes: specHasNaSentinel
        ? []
        : [...specStateClasses].filter((s) => !sourceStateClasses.has(s)),
      tokens: [...specTokens].filter((t) => !sourceTokens.has(t)),
    };

    if (
      missingInSpec.state_classes.length === 0 &&
      missingInSpec.tokens.length === 0 &&
      staleInSpec.state_classes.length === 0 &&
      staleInSpec.tokens.length === 0
    ) {
      continue;
    }

    violations.push(
      ...applyExceptions({
        dir: compDir,
        ruleId: RULE_ID,
        violations: [
          {
            comp,
            missing: missingInSpec,
            stale: staleInSpec,
            sourceFiles: sourceFiles.map((f) => path.relative(srcRootRel, f)),
          },
        ],
        rel: comp,
      }),
    );
  }

  if (violations.length === 0) {
    ok(`${componentRecords.length} component(s) checked; spec.yaml ↔ source state classes + tokens in sync.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-component-spec-vs-source:${RESET} ${violations.length} component(s) with spec/source drift\n\n`,
  );
  for (const v of violations) {
    process.stderr.write(`  ${v.comp}:\n`);
    if (v.kind === "spec_parse") {
      process.stderr.write(`    spec.yaml failed to parse: ${v.msg}\n`);
      continue;
    }
    if (v.missing.state_classes.length > 0) {
      process.stderr.write(
        `    state-* classes USED IN SOURCE but missing from spec.state_classes_consumed:\n`,
      );
      for (const s of v.missing.state_classes) process.stderr.write(`      - ${s}\n`);
    }
    if (v.missing.tokens.length > 0) {
      process.stderr.write(
        `    tokens USED IN SOURCE but missing from spec.tokens_consumed:\n`,
      );
      for (const t of v.missing.tokens) process.stderr.write(`      - ${t}\n`);
    }
    if (v.stale.state_classes.length > 0) {
      process.stderr.write(
        `    state-* classes DECLARED IN SPEC but not used in source (stale):\n`,
      );
      for (const s of v.stale.state_classes) process.stderr.write(`      - ${s}\n`);
    }
    if (v.stale.tokens.length > 0) {
      process.stderr.write(
        `    tokens DECLARED IN SPEC but not used in source (stale):\n`,
      );
      for (const t of v.stale.tokens) process.stderr.write(`      - ${t}\n`);
    }
  }
  process.stderr.write(
    `\n${DIM}Source files scanned: <Component>/*.ts(x) (excluding __stories__/__tests__/__specs__) + the matching shadcn baseline. Update spec.yaml's state_classes_consumed and tokens_consumed lists to match exactly what the source uses, then re-run.${RESET}\n`,
  );
  return 1;
}

function check_component_agent_operability(srcRoot = "src") {
  const GREEN = "\x1b[32m", RED = "\x1b[31m", YEL = "\x1b[33m", RST = "\x1b[0m";
  const cwd = process.cwd();
  const listMode = process.argv.includes("--list-debt");

  function readComponentRoots() {
    const def = ["src/components/ui", "src/components"];
    try {
      const a = join(cwd, ".standards", "autonomy.yaml");
      if (!existsSync(a)) return def;
      const txt = readFileSync(a, "utf8");
      const m = txt.match(/component_roots:\s*\n((?:\s*-\s*.+\n?)+)/);
      if (!m) return def;
      const roots = m[1].split("\n").map((l) => l.replace(/^\s*-\s*/, "").trim().replace(/^["']|["']$/g, "")).filter(Boolean);
      return roots.length ? roots : def;
    } catch { return def; }
  }

  function discover() {
    const comps = [];
    for (const root of readComponentRoots()) {
      const abs = resolve(cwd, root);
      if (!existsSync(abs)) continue;
      for (const name of readdirSync(abs)) {
        const dir = join(abs, name);
        let isDir = false;
        try { isDir = statSync(dir).isDirectory(); } catch { /* */ }
        if (!isDir) continue;
        if (!specFileExists(join(dir, "__specs__"))) continue;
        comps.push({ name, dir });
      }
    }
    return comps;
  }

  function manualFlowStatus(dir) {
    const mdir = join(dir, "__specs__", "manual");
    if (!existsSync(mdir)) return { ok: false, reason: "no __specs__/manual/ folder" };
    let mds = [];
    try { mds = readdirSync(mdir).filter((f) => f.endsWith(".md")); } catch { /* */ }
    if (!mds.length) return { ok: false, reason: "no manual/<flow>.md file" };
    for (const f of mds) {
      let t = "";
      try { t = readFileSync(join(mdir, f), "utf8"); } catch { continue; }
      const hasTitle = /^#\s+\S/m.test(t);
      const hasTarget = /^##\s+Target/m.test(t);
      const hasSteps = /^##\s+Steps?/m.test(t);
      const hasReport = /^##\s+Report/m.test(t);
      const reportRoute = /manual-results/.test(t);
      const escapeHatch = /\b(run the (unit|e2e) tests|see the test|automated tests? (cover|pass))\b/i.test(t) && !/POST/.test(t);
      if (hasTitle && hasTarget && hasSteps && hasReport && reportRoute && !escapeHatch) return { ok: true };
    }
    return { ok: false, reason: "manual/<flow>.md present but missing required sections (# title / ## Target / ## Steps / ## Report → manual-results)" };
  }

  function loadDebt() {
    try {
      const p = join(cwd, ".standards", "agent-operability-debt.json");
      if (!existsSync(p)) return new Set();
      const j = JSON.parse(readFileSync(p, "utf8"));
      return new Set(Array.isArray(j.debt) ? j.debt : []);
    } catch { return new Set(); }
  }

  try {
    const comps = discover();
    const nonCompliant = comps.filter((c) => !manualFlowStatus(c.dir).ok);

    if (listMode) {
      process.stdout.write(JSON.stringify(nonCompliant.map((c) => c.name).sort(), null, 2) + "\n");
      return 0;
    }

    const debt = loadDebt();
    const violations = nonCompliant.filter((c) => !debt.has(c.name));
    const inDebt = nonCompliant.filter((c) => debt.has(c.name));
    const compliant = comps.length - nonCompliant.length;

    if (violations.length) {
      console.log(`${RED}❌ verify-component-agent-operability${RST} — ${violations.length} component(s) lack a browser-executable manual flow and are NOT in the operability-debt ledger:`);
      for (const v of violations) console.log(`   ${v.name} — ${manualFlowStatus(v.dir).reason}`);
      console.log(`   Fix: add ${"`"}__specs__/manual/<flow>.md${"`"} (spec-derived, browser-executable) OR add the name to .standards/agent-operability-debt.json with a reason.`);
      return 1;
    }

    console.log(`${GREEN}✅ verify-component-agent-operability${RST} — ${compliant}/${comps.length} component(s) ship a manual flow; ${inDebt.length} in operability-debt ledger (burn down)${inDebt.length ? ": " + inDebt.map((c) => c.name).join(", ") : ""}.`);
    return 0;
  } catch (e) {
    console.log(`${YEL}⚠ verify-component-agent-operability skipped (internal error, fail-open): ${e.message}${RST}`);
    return 0;
  }
}

function check_composite_composition(srcRoot = "src") {
  const RULE_ID = "verify-composite-composition";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-composite-composition:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-composite-composition${RESET} — ${msg}\n`);
  }

  function findCompositeRoots(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".")) continue;
        const full = path.join(dir, e.name);
        const specsDir = path.join(full, "__specs__");
        if (specFileExists(specsDir)) {
          const byLocation =
            full.includes(path.sep + "components" + path.sep + "composites") ||
            full.match(new RegExp(`features\\${path.sep}[^${path.sep}]+\\${path.sep}components`));
          let byMarker = false;
          try {
            const mt = specMachineText(specsDir);
            byMarker = mt != null && /^\s*tier:\s*composite\s*$/m.test(mt);
          } catch {
            byMarker = false;
          }
          if (byLocation || byMarker) {
            found.push(full);
            continue;
          }
        }
        queue.push(full);
      }
    }
    return found;
  }

  function resolveAtomicLockStatus(atomicPath, repoRoot) {
    const absPath = path.resolve(repoRoot, atomicPath);
    if (!fs.existsSync(absPath)) return { exists: false };
    const specsDir = path.join(absPath, "__specs__");
    const complianceFile = resolveLockFile(specsDir);
    if (!fs.existsSync(complianceFile)) return { exists: true, locked: false };
    const lockRes = loadLock(specsDir);
    return { exists: true, locked: lockRes.ok && lockRes.value.status === "locked" };
  }

  function checkSourceImports(compositeFolder, consumedAtomics) {
    const violations = [];
    const sources = [];
    function walk(dir) {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (e.isDirectory()) {
          if (e.name === "__specs__" || e.name === "__tests__" || e.name === "__stories__") continue;
          walk(path.join(dir, e.name));
        } else if (/\.(tsx|ts)$/.test(e.name) && !e.name.includes(".d.ts")) {
          sources.push(path.join(dir, e.name));
        }
      }
    }
    walk(compositeFolder);

    for (const src of sources) {
      const text = fs.readFileSync(src, "utf8");
      for (const atomic of consumedAtomics) {
        if (!atomic.path) continue;
        const slashPath = atomic.path.replace(/\\/g, "/");
        const baseName = slashPath.split("/").pop();
        const internalPattern = new RegExp(
          `from\\s+['"][^'"]*${slashPath}/[^'"]+['"]`,
          "g",
        );
        const internalPatternBase = new RegExp(
          `from\\s+['"][^'"]*${baseName}/[^'"]+['"]`,
          "g",
        );
        const matches = [
          ...text.matchAll(internalPattern),
          ...text.matchAll(internalPatternBase),
        ];
        for (const m of matches) {
          const importLine = m[0];
          if (importLine.includes(`/${baseName}"`) || importLine.includes(`/${baseName}'`)) continue;
          if (importLine.includes(`/${baseName}/index`)) continue;
          violations.push({
            src: path.relative(process.cwd(), src),
            atomic: atomic.path,
            line: importLine,
            rule: "imports from atomic's internal files — must use the barrel (folder name only)",
          });
        }
      }
    }
    return violations;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const composites = findCompositeRoots(srcRootAbs);
  if (composites.length === 0) {
    ok(`no composite folders found under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];
  const repoRoot = path.resolve(process.cwd());

  for (const compositeFolder of composites) {
    const specRes = loadSpec(path.join(compositeFolder, "__specs__"));
    if (!specRes.ok) {
      allViolations.push({
        folder: compositeFolder,
        rule: `spec.yaml parse error: ${specRes.error}`,
      });
      continue;
    }
    const spec = specRes.value;

    if (spec?.tier !== "composite") continue;

    const consumed = Array.isArray(spec.consumed_atomics) ? spec.consumed_atomics : [];
    if (consumed.length === 0) {
      allViolations.push({
        folder: compositeFolder,
        rule: "composite spec.yaml has empty or missing consumed_atomics",
      });
      continue;
    }

    for (const atomic of consumed) {
      if (!atomic.path) {
        allViolations.push({
          folder: compositeFolder,
          rule: `consumed_atomics entry missing required 'path' field: ${JSON.stringify(atomic)}`,
        });
        continue;
      }
      const status = resolveAtomicLockStatus(atomic.path, repoRoot);
      if (!status.exists) {
        allViolations.push({
          folder: compositeFolder,
          rule: `consumed atomic does not exist: ${atomic.path}`,
        });
        continue;
      }
      if (!status.locked) {
        allViolations.push({
          folder: compositeFolder,
          rule: `consumed atomic is not status:locked: ${atomic.path}`,
        });
      }
      if (!atomic.locked_sha || typeof atomic.locked_sha !== "string" || atomic.locked_sha.length < 7) {
        allViolations.push({
          folder: compositeFolder,
          rule: `consumed_atomics entry "${atomic.path}" missing required locked_sha (full or short git SHA at lock time)`,
        });
      }
    }

    const frozen = spec.frozen_props ?? {};
    for (const [atomicName, props] of Object.entries(frozen)) {
      if (typeof props !== "object" || props === null) {
        allViolations.push({
          folder: compositeFolder,
          rule: `frozen_props.${atomicName} is not an object`,
        });
        continue;
      }
      for (const [propName, value] of Object.entries(props)) {
        if (
          value !== null &&
          typeof value === "object" &&
          !Array.isArray(value)
        ) {
          allViolations.push({
            folder: compositeFolder,
            rule: `frozen_props.${atomicName}.${propName} is not a literal (got nested object)`,
          });
        }
      }
    }

    const importViolations = checkSourceImports(compositeFolder, consumed);
    for (const iv of importViolations) {
      allViolations.push({
        folder: compositeFolder,
        rule: `${iv.rule} (in ${iv.src}): ${iv.line.trim()}`,
      });
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(`${composites.length} composite(s) checked; all consumed atomics locked + frozen props valid.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-composite-composition:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Per COMPOSITE_CREATION.yaml.thin_spec_doctrine, every consumed atomic must exist + be status:locked. Imports must use the atomic's barrel.${RESET}\n`,
  );
  return 1;
}

function check_composite_state_propagation(srcRoot = "src") {
  const RULE_ID = "verify-composite-state-propagation";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-composite-state-propagation:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-composite-state-propagation${RESET} — ${msg}\n`);
  }

  function findCompositeRoots(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".")) continue;
        const full = path.join(dir, e.name);
        const specsDir = path.join(full, "__specs__");
        if (specFileExists(specsDir)) {
          const byLocation =
            full.includes(path.sep + "components" + path.sep + "composites") ||
            full.match(new RegExp(`features\\${path.sep}[^${path.sep}]+\\${path.sep}components`));
          let byMarker = false;
          try {
            const mt = specMachineText(specsDir);
            byMarker = mt != null && /^\s*tier:\s*composite\s*$/m.test(mt);
          } catch {
            byMarker = false;
          }
          if (byLocation || byMarker) {
            found.push(full);
            continue;
          }
        }
        queue.push(full);
      }
    }
    return found;
  }

  function collectSources(compositeFolder) {
    const sources = [];
    function walk(dir) {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (e.isDirectory()) {
          if (e.name === "__specs__" || e.name === "__tests__" || e.name === "__stories__") continue;
          walk(path.join(dir, e.name));
        } else if (/\.tsx$/.test(e.name)) {
          sources.push(path.join(dir, e.name));
        }
      }
    }
    walk(compositeFolder);
    return sources;
  }

  function atomicNameFromPath(atomicPath) {
    if (!atomicPath) return null;
    return atomicPath.replace(/\\/g, "/").split("/").pop();
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const composites = findCompositeRoots(srcRootAbs);
  if (composites.length === 0) {
    ok(`no composite folders found under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];

  for (const compositeFolder of composites) {
    const specRes = loadSpec(path.join(compositeFolder, "__specs__"));
    if (!specRes.ok) continue;
    const spec = specRes.value;
    if (spec?.tier !== "composite") continue;

    const consumed = Array.isArray(spec.consumed_atomics) ? spec.consumed_atomics : [];
    const consumedNames = new Set(
      consumed.map((a) => atomicNameFromPath(a.path)).filter(Boolean),
    );
    const normalizeName = (n) => n.replace(/-/g, "").toLowerCase();
    const consumedNamesNorm = new Set([...consumedNames].map(normalizeName));

    const propagation = Array.isArray(spec.state_propagation) ? spec.state_propagation : [];
    const sources = collectSources(compositeFolder);
    const combinedSource = sources.map((p) => fs.readFileSync(p, "utf8")).join("\n");

    for (const rule of propagation) {
      const target = rule.atomic_target;
      const propName = rule.prop_set_on_atomic;
      if (!target || !propName) continue;
      if (target.toLowerCase().includes("(no") || target === "n/a") continue;

      const atomicName = consumed.find(
        (a) => atomicNameFromPath(a.path) === target,
      )
        ? target
        : consumed.find(
            (a) =>
              atomicNameFromPath(a.path)?.toLowerCase() === target.toLowerCase(),
          )?.path?.split("/")?.pop() ?? target;

      const propRegex = new RegExp(
        `<\\s*${atomicName}\\b[^>]*\\b${propName}\\b`,
        "i",
      );
      if (!propRegex.test(combinedSource)) {
        allViolations.push({
          folder: compositeFolder,
          rule: `state_propagation declares "${rule.composite_state}" → ${atomicName}.${propName} but source has no <${atomicName} ... ${propName}=...> assignment`,
        });
      }
    }

    const jsxElementRegex = /<\s*([A-Z][A-Za-z0-9_]*)\b/g;
    const usedAtomicNames = new Set();
    for (const m of combinedSource.matchAll(jsxElementRegex)) {
      usedAtomicNames.add(m[1]);
    }
    for (const used of usedAtomicNames) {
      if (used.startsWith(spec.component ?? "X")) continue;
      if (/^(Fragment|StrictMode|Suspense|Provider|Consumer)$/.test(used)) continue;
      if (consumedNames.has(used)) continue;
      if (consumedNamesNorm.has(normalizeName(used))) continue;
      const isAtomicLike =
        /Button|Select|Input|Dialog|Drawer|Tooltip|Badge|Card|Tabs|Progress|Alert|Banner|Spinner|StateMessage|ListRow|Switch|Toggle|Checkbox|Textarea|Label|Separator|Sonner|Accordion/.test(
          used,
        );
      if (isAtomicLike) {
        allViolations.push({
          folder: compositeFolder,
          rule: `source renders <${used}> but it is NOT in spec.yaml.consumed_atomics — add it or remove the usage`,
        });
      }
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(
      `${composites.length} composite(s) checked; all state_propagation rules implemented + consumed_atomics match source.`,
    );
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-composite-state-propagation:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Per COMPOSITE_CREATION.yaml, declared state_propagation rules must be implemented; every JSX atomic must appear in consumed_atomics.${RESET}\n`,
  );
  return 1;
}

function check_page_landmarks(srcRoot = "src") {
  const RULE_ID = "verify-page-landmarks";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  const SEMANTIC_LANDMARKS = ["header", "nav", "main", "aside", "footer"];

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-page-landmarks:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-page-landmarks${RESET} — ${msg}\n`);
  }

  function findPageRoots(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".")) continue;
        const full = path.join(dir, e.name);
        const specsDir = path.join(full, "__specs__");
        if (specFileExists(specsDir)) {
          try {
            const text = specMachineText(specsDir);
            if (text != null && /^\s*tier:\s*page\s*$/m.test(text)) {
              found.push(full);
              continue;
            }
          } catch {
            continue;
          }
        }
        queue.push(full);
      }
    }
    return found;
  }

  function collectSourceText(pageFolder) {
    const sources = [];
    function walk(dir) {
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const e of entries) {
        if (e.isDirectory()) {
          if (e.name === "__specs__" || e.name === "__tests__" || e.name === "__stories__") continue;
          walk(path.join(dir, e.name));
        } else if (/\.tsx$/.test(e.name)) {
          sources.push(fs.readFileSync(path.join(dir, e.name), "utf8"));
        }
      }
    }
    walk(pageFolder);
    return sources.join("\n");
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const pages = findPageRoots(srcRootAbs);
  if (pages.length === 0) {
    ok(`no page folders found under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];

  for (const pageFolder of pages) {
    const specRes = loadSpec(path.join(pageFolder, "__specs__"));
    if (!specRes.ok) {
      allViolations.push({
        folder: pageFolder,
        rule: `spec.yaml parse error: ${specRes.error}`,
      });
      continue;
    }
    const spec = specRes.value;

    const surfaceType = spec?.surface_type;
    const landmarks = Array.isArray(spec.landmark_structure) ? spec.landmark_structure : [];
    const sourceText = collectSourceText(pageFolder);
    if (sourceText.length === 0) continue;

    const relevantLandmarks = landmarks.filter((l) => {
      const present = Array.isArray(l.present_in_surface_types) ? l.present_in_surface_types : [];
      return present.length === 0 || present.includes(surfaceType);
    });

    for (const l of relevantLandmarks) {
      const tag = l.element_tag;
      if (!tag) {
        allViolations.push({
          folder: pageFolder,
          rule: `landmark_structure entry missing element_tag`,
        });
        continue;
      }
      const openTagRegex = new RegExp(`<\\s*${tag}\\b`);
      if (!openTagRegex.test(sourceText)) {
        allViolations.push({
          folder: pageFolder,
          rule: `landmark declared in spec.yaml (${l.landmark_role} → ${tag}) has no matching <${tag}> open tag in source`,
        });
      }
    }

    const declaredTags = new Set(relevantLandmarks.map((l) => l.element_tag).filter(Boolean));
    for (const tag of SEMANTIC_LANDMARKS) {
      const openTagRegex = new RegExp(`<\\s*${tag}\\b`);
      if (openTagRegex.test(sourceText) && !declaredTags.has(tag)) {
        const isExempt = (surfaceType === "sidepanel" || surfaceType === "popup") && tag !== "main";
        if (!isExempt) {
          allViolations.push({
            folder: pageFolder,
            rule: `source uses <${tag}> but landmark_structure does not declare it`,
          });
        }
      }
    }

    if (spec.skip_link?.exists === true) {
      const target = spec.skip_link?.target_selector;
      if (target && target.startsWith("#")) {
        const id = target.slice(1);
        const idRegex = new RegExp(`id\\s*=\\s*["']${id}["']`);
        if (!idRegex.test(sourceText)) {
          allViolations.push({
            folder: pageFolder,
            rule: `skip-link declared with target ${target} but source has no element with id="${id}"`,
          });
        }
      }
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(`${pages.length} page(s) checked; landmark structure matches source.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-page-landmarks:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Per PAGE_CREATION.yaml.verifiers, every declared landmark needs source coverage; every source landmark needs spec declaration.${RESET}\n`,
  );
  return 1;
}

function check_page_state_machine(srcRoot = "src") {
  const RULE_ID = "verify-page-state-machine";

  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-page-state-machine:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-page-state-machine${RESET} — ${msg}\n`);
  }

  function findPageRoots(srcRoot) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".")) continue;
        const full = path.join(dir, e.name);
        const specsDir = path.join(full, "__specs__");
        if (specFileExists(specsDir)) {
          try {
            const text = specMachineText(specsDir);
            if (text != null && /^\s*tier:\s*page\s*$/m.test(text)) {
              found.push(full);
              continue;
            }
          } catch {
            continue;
          }
        }
        queue.push(full);
      }
    }
    return found;
  }

  function collectSources(folder, includeTests) {
    const sources = [];
    function walk(dir) {
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const e of entries) {
        if (e.isDirectory()) {
          if (e.name === "__specs__" || e.name === "__stories__") continue;
          if (!includeTests && e.name === "__tests__") continue;
          walk(path.join(dir, e.name));
        } else if (/\.(tsx|ts)$/.test(e.name)) {
          sources.push({ path: path.join(dir, e.name), text: fs.readFileSync(path.join(dir, e.name), "utf8") });
        }
      }
    }
    walk(folder);
    return sources;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const pages = findPageRoots(srcRootAbs);
  if (pages.length === 0) {
    ok(`no page folders found under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];

  for (const pageFolder of pages) {
    const specRes = loadSpec(path.join(pageFolder, "__specs__"));
    if (!specRes.ok) {
      allViolations.push({
        folder: pageFolder,
        rule: `spec.yaml parse error: ${specRes.error}`,
      });
      continue;
    }
    const spec = specRes.value;

    const machine = spec.state_machine ?? {};
    const states = Array.isArray(machine.states) ? machine.states : [];
    const transitions = Array.isArray(machine.transitions) ? machine.transitions : [];
    if (states.length === 0) {
      allViolations.push({
        folder: pageFolder,
        rule: "spec.yaml.state_machine.states is empty — every page declares a state machine (idle-only is fine)",
      });
      continue;
    }

    const renderSources = collectSources(pageFolder, false);
    const testSources = collectSources(path.join(pageFolder, "__tests__"), true);

    const combinedSource = renderSources.map((s) => s.text).join("\n");
    const combinedTests = testSources.map((s) => s.text).join("\n");

    for (const state of states) {
      const stateName = String(state).replace(/[^a-zA-Z0-9_-]/g, "");
      if (stateName === "idle") continue;
      const stateRegex = new RegExp(
        `["'\`]${stateName}["'\`]|\\.${stateName}\\b|case\\s+${stateName}\\b|state\\s*===?\\s*["'\`]${stateName}`,
        "i",
      );
      if (!stateRegex.test(combinedSource)) {
        allViolations.push({
          folder: pageFolder,
          rule: `state_machine declares state "${stateName}" but source has no render branch referencing it`,
        });
      }
    }

    if (testSources.length > 0) {
      for (const t of transitions) {
        const from = String(t.from ?? "").replace(/[^a-zA-Z0-9_-]/g, "");
        const to = String(t.to ?? "").replace(/[^a-zA-Z0-9_-]/g, "");
        if (!from || !to || from === "any") continue;
        const transitionRegex = new RegExp(`${from}.*${to}|${to}.*${from}`, "i");
        if (!transitionRegex.test(combinedTests)) {
          allViolations.push({
            folder: pageFolder,
            rule: `state_machine transition "${from} → ${to}" has no matching test in __tests__/`,
          });
        }
      }
    }
  }

  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(`${pages.length} page(s) checked; state machines declared, rendered, and tested.`);
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-page-state-machine:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Per PAGE_CREATION.yaml.verifiers, every declared state needs source coverage; every declared transition needs a test.${RESET}\n`,
  );
  return 1;
}

function check_cross_tier_freshness(srcRoot = "src") {
  const RED = "\x1b[31m";
  const GREEN = "\x1b[32m";
  const YELLOW = "\x1b[33m";
  const DIM = "\x1b[2m";
  const RESET = "\x1b[0m";

  function loadYaml() {
    try {
      const require = createRequire(process.cwd() + "/");
      return require("yaml");
    } catch {
      return null;
    }
  }

  function fail(msg) {
    process.stderr.write(`${RED}❌ verify-cross-tier-freshness:${RESET} ${msg}\n`);
    process.exit(1);
  }

  function ok(msg) {
    process.stdout.write(`${GREEN}✅ verify-cross-tier-freshness${RESET} — ${msg}\n`);
  }

  function warn(msg) {
    process.stdout.write(`${YELLOW}⚠  verify-cross-tier-freshness:${RESET} ${msg}\n`);
  }

  function findSpecsByTier(srcRoot, tier) {
    const found = [];
    const queue = [srcRoot];
    while (queue.length > 0) {
      const dir = queue.shift();
      if (!fs.existsSync(dir)) continue;
      let entries;
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        continue;
      }
      for (const e of entries) {
        if (!e.isDirectory()) continue;
        if (e.name === "node_modules" || e.name.startsWith(".")) continue;
        const full = path.join(dir, e.name);
        const specsDir = path.join(full, "__specs__");
        if (specFileExists(specsDir)) {
          try {
            const text = specMachineText(specsDir);
            if (text != null && new RegExp(`^\\s*tier:\\s*${tier}\\s*$`, "m").test(text)) {
              found.push({ folder: full, specPath: resolveSpecFile(specsDir) });
              continue;
            }
          } catch {
            continue;
          }
        }
        queue.push(full);
      }
    }
    return found;
  }

  function checkFreshness(consumerFolder, consumed, label, repoRoot) {
    const violations = [];
    for (const dep of consumed ?? []) {
      if (!dep.path || !dep.locked_sha) continue;
      const absDep = path.resolve(repoRoot, dep.path);
      if (!fs.existsSync(absDep)) continue;
      try {
        const cmd = `git log "${dep.locked_sha}..HEAD" --oneline -- "${dep.path}"`;
        const output = execSync(cmd, {
          cwd: repoRoot,
          stdio: ["ignore", "pipe", "ignore"],
          encoding: "utf8",
        }).trim();
        if (output.length > 0) {
          const commits = output.split("\n").length;
          violations.push({
            consumer: consumerFolder,
            rule: `${label} "${dep.path}" pinned to ${dep.locked_sha} but has ${commits} commit(s) since — re-pin locked_sha to current HEAD and re-validate`,
          });
        }
      } catch {
        warn(
          `git log failed for ${dep.path} pinned to ${dep.locked_sha}; skipping freshness check (SHA may not exist in history yet)`,
        );
      }
    }
    return violations;
  }

  const arg = srcRoot;
  const srcRootAbs = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRootAbs)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return 0;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  let repoRoot;
  try {
    repoRoot = execSync("git rev-parse --show-toplevel", {
      cwd: process.cwd(),
      encoding: "utf8",
    }).trim();
  } catch {
    warn(`not inside a git repo; freshness check skipped.`);
    ok(`skipped (not a git repo).`);
    return 0;
  }

  const composites = findSpecsByTier(srcRootAbs, "composite");
  const pages = findSpecsByTier(srcRootAbs, "page");
  if (composites.length === 0 && pages.length === 0) {
    ok(`no composite or page specs under ${arg}; nothing to verify.`);
    return 0;
  }

  const allViolations = [];

  for (const c of composites) {
    const specRes = loadSpec(path.dirname(c.specPath));
    if (!specRes.ok) continue;
    const spec = specRes.value;
    allViolations.push(...checkFreshness(c.folder, spec.consumed_atomics, "consumed atomic", repoRoot));
  }

  for (const p of pages) {
    const specRes = loadSpec(path.dirname(p.specPath));
    if (!specRes.ok) continue;
    const spec = specRes.value;
    allViolations.push(...checkFreshness(p.folder, spec.consumed_composites, "consumed composite", repoRoot));
    allViolations.push(...checkFreshness(p.folder, spec.consumed_atomics, "consumed atomic", repoRoot));
  }

  if (allViolations.length === 0) {
    ok(
      `${composites.length} composite(s), ${pages.length} page(s) checked; no stale lower-tier dependencies.`,
    );
    return 0;
  }

  process.stderr.write(
    `${RED}❌ verify-cross-tier-freshness:${RESET} ${allViolations.length} stale dependency reference(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.consumer)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Either: (a) update locked_sha to the dep's current HEAD and re-run the consumer's verifier chain to re-validate; OR (b) revert the dep to the pinned SHA.${RESET}\n`,
  );
  return 1;
}

function check_ui_design_locked(srcRoot = "src") {
  const SOURCE_ROOT = srcRoot;
  const REPO_ROOT = process.cwd();
  const absRoot = join(REPO_ROOT, SOURCE_ROOT);

  const IGNORE_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "coverage", ".git",
  ]);

  const UI_REQUIRED_INVOCATION_TYPES = new Set(["ui", "server-action"]);
  const LOCK_MARKER_REGEX = /<!--\s*ui-locked:\s*\d{4}-\d{2}-\d{2}\s*-->/;

  function resolveYaml() {
    try {
      return createRequire(join(REPO_ROOT, "package.json"))("yaml");
    } catch {}
    let dir = REPO_ROOT;
    while (dir !== dirname(dir)) {
      const cand = join(dir, "node_modules", "yaml");
      if (existsSync(cand)) {
        try {
          return createRequire(join(cand, "package.json"))("yaml");
        } catch {}
      }
      dir = dirname(dir);
    }
    try {
      return createRequire(import.meta.url)("yaml");
    } catch {}
    return null;
  }

  const YAML = resolveYaml();
  if (!YAML) {
    process.stderr.write(
      "❌ verify-ui-design-locked: missing `yaml` devDependency.\n" +
        "   Install it:  pnpm add -D yaml\n",
    );
    return 1;
  }

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-ui-design-locked — no ${SOURCE_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  const specDirs = new Set();

  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (IGNORE_DIRS.has(entry.name)) continue;
        walk(join(dir, entry.name));
        continue;
      }
      if ((entry.name === "spec.md" || entry.name === "spec.yaml") && dir.endsWith("__specs__")) {
        specDirs.add(dir);
      }
    }
  }

  walk(absRoot);

  // md-first resolved path per __specs__ dir (dedup when both spec.md + spec.yaml exist).
  const specYamlPaths = [...specDirs].map((d) => resolveSpecFile(d));

  if (specYamlPaths.length === 0) {
    process.stdout.write(
      "✅ verify-ui-design-locked — no __specs__/spec.yaml found; nothing to check.\n",
    );
    return 0;
  }

  const violations = [];

  for (const specPath of specYamlPaths) {
    const rel = relative(REPO_ROOT, specPath);
    const specRes = loadSpec(dirname(specPath));
    if (!specRes.ok) {
      violations.push(`${rel}: YAML parse error — ${specRes.error}`);
      continue;
    }
    const doc = specRes.value;
    if (!doc || typeof doc !== "object") continue;

    const invType = doc.invocation && doc.invocation.type;
    const optOut = doc.ui_design === "not-applicable";
    const autoRequired = UI_REQUIRED_INVOCATION_TYPES.has(invType);
    const explicitRequired = doc.ui_design === "required";
    const required = explicitRequired || (autoRequired && !optOut);

    if (!required) continue;

    const flows = (doc.links && Array.isArray(doc.links.flows)) ? doc.links.flows : [];
    if (flows.length === 0) {
      violations.push(`${rel}: ui_design required but spec.yaml.links.flows is empty`);
      continue;
    }

    const specsDir = dirname(specPath);
    const uiDir = join(specsDir, "ui");

    for (const flowEntry of flows) {
      if (typeof flowEntry !== "string") continue;
      const flowFile = basename(flowEntry);
      const flowBase = flowFile.replace(/\.flow\.ya?ml$/, "");
      const uiFile = join(uiDir, `${flowBase}.md`);
      const uiRel = relative(REPO_ROOT, uiFile);

      if (!existsSync(uiFile)) {
        violations.push(`${uiRel}: missing UI design doc (required by ${rel})`);
        continue;
      }

      let uiContent;
      try {
        uiContent = readFileSync(uiFile, "utf8");
      } catch (e) {
        violations.push(`${uiRel}: read error — ${e.message}`);
        continue;
      }

      if (!LOCK_MARKER_REGEX.test(uiContent)) {
        violations.push(
          `${uiRel}: missing lock marker \`<!-- ui-locked: YYYY-MM-DD -->\` ` +
            `(user inserts after approving the design; spec-writer NEVER self-signs)`,
        );
      }
    }
  }

  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-ui-design-locked — ${specYamlPaths.length} spec(s) checked; all UI designs locked.\n`,
    );
    return 0;
  }

  process.stderr.write(
    `❌ verify-ui-design-locked: ${violations.length} violation(s)\n\n`,
  );
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write(
    `\nThe coder phase is blocked until every required UI design carries the lock marker.\n` +
      `User inserts \`<!-- ui-locked: YYYY-MM-DD -->\` after approving each \`__specs__/ui/<flow>.md\`.\n` +
      `Template: ~/.claude/standards/templates/ui-flow.md.template\n`,
  );
  return 1;
}

async function check_ui_screenshots_match_designs(srcRoot = "src") {
  const REPO_ROOT = resolve(process.cwd());
  const SRC_ROOT = resolve(REPO_ROOT, "src");

  const SKIP_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "out", ".git", "coverage",
  ]);

  const require = createRequire(import.meta.url);

  let YAML, puppeteer;
  const missingDeps = [];
  try { YAML = require("yaml"); } catch { missingDeps.push("yaml"); }
  try { puppeteer = require("puppeteer"); } catch { missingDeps.push("puppeteer"); }

  if (missingDeps.length > 0) {
    process.stderr.write(
      `🚧 verify-ui-screenshots-match-designs: BLOCKED — missing devDependencies: ${missingDeps.join(", ")}\n` +
      `   Install them:  pnpm add -D ${missingDeps.join(" ")}\n`,
    );
    return 2;
  }

  if (!existsSync(SRC_ROOT)) {
    process.stdout.write(
      `✅ verify-ui-screenshots-match-designs — no src/ in this repo; nothing to check.\n`,
    );
    return 0;
  }

  function readRepoConfig() {
    const readmePath = join(REPO_ROOT, "README.yaml");
    if (!existsSync(readmePath)) return {};
    try { return YAML.parse(readFileSync(readmePath, "utf8")) ?? {}; }
    catch { return {}; }
  }

  const repoConfig = readRepoConfig();
  const THRESHOLD = Number(repoConfig.ui_screenshot_match_threshold ?? 85);
  const DEV_SERVER_URL = String(repoConfig.ui_screenshot_dev_server_url ?? "http://localhost:3000");

  const specDirs = new Set();

  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        walk(join(dir, entry.name));
        continue;
      }
      if ((entry.name === "spec.md" || entry.name === "spec.yaml") && dir.endsWith("__specs__")) {
        specDirs.add(dir);
      }
    }
  }
  walk(SRC_ROOT);

  // md-first resolved path per __specs__ dir (dedup when both spec.md + spec.yaml exist).
  const specPaths = [...specDirs].map((d) => resolveSpecFile(d));

  if (specPaths.length === 0) {
    process.stdout.write(
      `✅ verify-ui-screenshots-match-designs — no __specs__/spec.yaml files; nothing to check.\n`,
    );
    return 0;
  }

  const UI_TYPES = new Set(["ui", "server-action"]);

  function listChecksForSpec(specPath) {
    const specsDir = dirname(specPath);
    const specRes = loadSpec(specsDir);
    if (!specRes.ok) return { kind: "error", reason: `YAML parse: ${specRes.error}` };
    const spec = specRes.value;

    const inv = spec?.invocation;
    const autoRequired = inv && UI_TYPES.has(inv.type);
    const optOut = spec?.ui_design === "not-applicable";
    const explicitRequired = spec?.ui_design === "required";
    const required = explicitRequired || (autoRequired && !optOut);
    if (!required) return { kind: "skip" };

    const flows = (spec?.links?.flows ?? []).filter((f) => typeof f === "string");
    if (flows.length === 0) return { kind: "error", reason: "ui_design required but spec.yaml.links.flows is empty" };

    const checks = [];
    for (const flowEntry of flows) {
      const flowBase = basename(flowEntry).replace(/\.flow\.ya?ml$/, "");
      const manualPath = join(specsDir, "manual", `${flowBase}.yaml`);
      if (!existsSync(manualPath)) {
        checks.push({ flow: flowBase, state: null, error: `manual playbook missing at ${manualPath}` });
        continue;
      }
      let manual;
      try { manual = YAML.parse(readFileSync(manualPath, "utf8")); }
      catch (e) { checks.push({ flow: flowBase, state: null, error: `manual.yaml parse: ${e.message}` }); continue; }

      const stateNames = manual?.states && typeof manual.states === "object"
        ? Object.keys(manual.states)
        : ["entry"];

      for (const state of stateNames) {
        checks.push({ flow: flowBase, state, manual, manualPath, specsDir });
      }
    }
    return { kind: "checks", checks };
  }

  async function screenshotState(browserPage, manualYaml, state) {
    const url = manualYaml?.start
      ? new URL(manualYaml.start, DEV_SERVER_URL).toString()
      : DEV_SERVER_URL;
    await browserPage.goto(url, { waitUntil: "networkidle0" });
    const stateSteps = manualYaml?.states?.[state]?.steps ?? [];
    for (const step of stateSteps) {
      if (typeof step !== "object") continue;
      if (step.click) await browserPage.click(step.click);
      if (step.type)  await browserPage.type(step.selector, step.type);
      if (step.wait)  await new Promise((r) => setTimeout(r, Number(step.wait)));
      if (step.waitForSelector) await browserPage.waitForSelector(step.waitForSelector);
    }
    return browserPage.screenshot({ type: "png", fullPage: true });
  }

  function readMatchResult(specsDir, flow, state) {
    const p = join(specsDir, "ui", `${flow}.match-${state}.json`);
    if (!existsSync(p)) return null;
    try { return JSON.parse(readFileSync(p, "utf8")); }
    catch (e) { return { __invalid__: true, error: e.message }; }
  }

  function writeDiffMd(specsDir, flow, state, screenshotPath, designPath, matchResult) {
    const p = join(specsDir, "ui", `${flow}.diff-${state}.md`);
    const body = [
      `# UI diff — ${flow} / ${state}`,
      ``,
      `**Score:** ${matchResult.score} / 100 (threshold ${THRESHOLD})  `,
      `**Reviewed at:** ${matchResult.reviewed_at}  `,
      `**Reviewer:** ${matchResult.reviewer}`,
      ``,
      `## Discrepancies`,
      ``,
      ...matchResult.discrepancies.map((d) => `- ${d}`),
      ``,
      `## Design (target)`,
      ``,
      `![design](${relative(dirname(p), designPath)})`,
      ``,
      `## Screenshot (implementation)`,
      ``,
      `![screenshot](${relative(dirname(p), screenshotPath)})`,
      ``,
    ].join("\n");
    writeFileSync(p, body);
    return p;
  }

  const reviewQueue = [];
  const blocks = [];
  const failures = [];

  let browser, browserPage;

  try {
    for (const specPath of specPaths) {
      const rel = relative(REPO_ROOT, specPath);
      const planResult = listChecksForSpec(specPath);
      if (planResult.kind === "skip") continue;
      if (planResult.kind === "error") { blocks.push(`${rel}: ${planResult.reason}`); continue; }

      for (const check of planResult.checks) {
        if (check.error) { blocks.push(`${rel}: flow ${check.flow}: ${check.error}`); continue; }

        const { flow, state, manual, specsDir } = check;

        const designRes = resolveDesign(specsDir, flow, state);
        if (designRes.kind !== "png-bytes") {
          blocks.push(`${rel}: flow ${flow} state ${state}: ${designRes.reason}`);
          continue;
        }

        const existing = readMatchResult(specsDir, flow, state);
        if (existing && !existing.__invalid__) {
          if (existing.score < THRESHOLD) {
            const screenshotPath = join(specsDir, "ui", `${flow}.screenshot-${state}.png`);
            const diffPath = writeDiffMd(specsDir, flow, state, screenshotPath, designRes.location, existing);
            failures.push({ spec: rel, flow, state, score: existing.score, diff: relative(REPO_ROOT, diffPath), discrepancies: existing.discrepancies });
          }
          continue;
        }
        if (existing && existing.__invalid__) {
          blocks.push(`${rel}: flow ${flow} state ${state}: match-result file invalid JSON — ${existing.error}`);
          continue;
        }

        if (!browser) {
          browser = await puppeteer.launch({ headless: "new" });
          browserPage = await browser.newPage();
          await browserPage.setViewport({ width: 1440, height: 900 });
        }

        let screenshotPng;
        try { screenshotPng = await screenshotState(browserPage, manual, state); }
        catch (e) {
          blocks.push(`${rel}: flow ${flow} state ${state}: screenshot failed — ${e.message}`);
          continue;
        }

        const screenshotPath = join(specsDir, "ui", `${flow}.screenshot-${state}.png`);
        mkdirSync(dirname(screenshotPath), { recursive: true });
        writeFileSync(screenshotPath, screenshotPng);

        reviewQueue.push({
          spec: rel,
          flow,
          state,
          screenshot: relative(REPO_ROOT, screenshotPath),
          design: relative(REPO_ROOT, designRes.location),
          result_path: relative(REPO_ROOT, join(specsDir, "ui", `${flow}.match-${state}.json`)),
        });
      }
    }
  } finally {
    if (browser) await browser.close();
  }

  if (reviewQueue.length > 0) {
    const bySpecDir = new Map();
    for (const item of reviewQueue) {
      const dir = dirname(join(REPO_ROOT, item.spec));
      const queue = bySpecDir.get(dir) ?? [];
      queue.push(item);
      bySpecDir.set(dir, queue);
    }
    for (const [dir, items] of bySpecDir) {
      const manifestPath = join(dir, "ui", ".review-queue.json");
      mkdirSync(dirname(manifestPath), { recursive: true });
      writeFileSync(manifestPath, JSON.stringify({ pending: items }, null, 2) + "\n");
    }
  }

  if (blocks.length > 0) {
    process.stderr.write(`🚧 verify-ui-screenshots-match-designs: BLOCKED (${blocks.length} input(s) missing)\n\n`);
    for (const b of blocks) process.stderr.write(`  ${b}\n`);
    return 2;
  }
  if (reviewQueue.length > 0) {
    process.stderr.write(
      `🚧 verify-ui-screenshots-match-designs: ${reviewQueue.length} (flow,state) pair(s) need agent review\n\n` +
      `   Verifier agent: read the manifest, score each pair, write the result file. Then re-run this gate.\n\n` +
      `   Per spec, the review queue is at __specs__/ui/.review-queue.json.\n\n`,
    );
    for (const item of reviewQueue) {
      process.stderr.write(`  ${item.spec} / ${item.flow} / ${item.state}\n`);
      process.stderr.write(`     screenshot: ${item.screenshot}\n`);
      process.stderr.write(`     design:     ${item.design}\n`);
      process.stderr.write(`     write to:   ${item.result_path}\n`);
    }
    return 2;
  }
  if (failures.length === 0) {
    process.stdout.write(`✅ verify-ui-screenshots-match-designs — every reviewed UI state scores ≥ ${THRESHOLD}.\n`);
    return 0;
  }
  process.stderr.write(`❌ verify-ui-screenshots-match-designs: ${failures.length} state(s) below threshold (${THRESHOLD})\n\n`);
  for (const f of failures) {
    process.stderr.write(`  ${f.spec} / ${f.flow} / ${f.state}: score ${f.score} → ${f.diff}\n`);
    for (const d of f.discrepancies) process.stderr.write(`     - ${d}\n`);
  }
  return 1;
}

// ===========================================================================
// Dispatcher
// ===========================================================================

function isCliInvocation(importMetaUrl, argv1) {
  if (argv1 === undefined || argv1 === "") return false;
  return importMetaUrl === pathToFileURL(argv1).href;
}

const CHECKS = {
  "component-tokens": check_component_tokens,
  "component-state-vocab": check_component_state_vocab,
  "component-design-locked": check_component_design_locked,
  "component-spec": check_component_spec,
  "component-research-cited": check_component_research_cited,
  "component-design-self-lock-eligible": check_component_design_self_lock_eligible,
  "component-research-depth": check_component_research_depth,
  "component-spec-matrix-completeness": check_component_spec_matrix_completeness,
  "component-stakes-honest": check_component_stakes_honest,
  "component-storybook-docs": check_component_storybook_docs,
  "component-spec-vs-source": check_component_spec_vs_source,
  "component-agent-operability": check_component_agent_operability,
  "composite-composition": check_composite_composition,
  "composite-state-propagation": check_composite_state_propagation,
  "page-landmarks": check_page_landmarks,
  "page-state-machine": check_page_state_machine,
  "cross-tier-freshness": check_cross_tier_freshness,
  "ui-design-locked": check_ui_design_locked,
  "ui-components-compliance": () => runAudit(),
  "ui-screenshots-match-designs": check_ui_screenshots_match_designs,
};

// Stable default order — every sub-check EXCEPT ui-screenshots-match-designs
// (heavy / live-API; runs only under --full or an explicit --check).
const DEFAULT_ORDER = [
  "component-tokens",
  "component-state-vocab",
  "component-design-locked",
  "component-spec",
  "component-research-cited",
  "component-design-self-lock-eligible",
  "component-research-depth",
  "component-spec-matrix-completeness",
  "component-stakes-honest",
  "component-storybook-docs",
  "component-spec-vs-source",
  "component-agent-operability",
  "composite-composition",
  "composite-state-propagation",
  "page-landmarks",
  "page-state-machine",
  "cross-tier-freshness",
  "ui-design-locked",
  "ui-components-compliance",
];

if (isCliInvocation(import.meta.url, process.argv[1])) {
  const argv = process.argv.slice(2);
  let checkName = null;
  let full = false;
  const positionals = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--check") {
      checkName = argv[i + 1];
      i += 1;
    } else if (a === "--full") {
      full = true;
    } else if (a.startsWith("--")) {
      // passthrough flag (e.g. --list-debt, read directly by a sub-check); ignored here
    } else {
      positionals.push(a);
    }
  }
  const srcRoot = positionals[0] || "src";

  if (checkName) {
    const fn = CHECKS[checkName];
    if (!fn) {
      process.stderr.write(`verify-component: unknown check "${checkName}"\n`);
      process.exit(2);
    }
    const code = await fn(srcRoot);
    process.exit(typeof code === "number" ? code : 0);
  } else {
    const order = [...DEFAULT_ORDER];
    if (full) order.push("ui-screenshots-match-designs");
    let anyFail = false;
    for (const slug of order) {
      const code = await CHECKS[slug](srcRoot);
      if (typeof code === "number" && code !== 0) anyFail = true;
    }
    process.exit(anyFail ? 1 : 0);
  }
}
